    JourneyContent("satire-101", JourneyContentKind.SATIRE, "Anschluss erreicht: ein kleines persönliches Finale ohne Siegerehrung.", "Connection made: a small personal final without a medal ceremony.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-102", JourneyContentKind.SATIRE, "Wenn beide Züge dieselbe Verspätung hätten, wäre das schon eine Form von Teamarbeit.", "If both trains had the same delay, that would at least be a form of teamwork.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-103", JourneyContentKind.SATIRE, "Mein Umstieg ist sportlich. Ich wäre lieber gemütlich.", "My transfer is athletic. I would rather take it easy.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-104", JourneyContentKind.SATIRE, "Auf dem Reiseplan liegen zwei Gleise nebeneinander. Im Bahnhof liegt dazwischen ein Abenteuer.", "Two platforms sit side by side on the journey plan. In the station, an adventure lies between them.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-105", JourneyContentKind.SATIRE, "Eine gute Anschlussverbindung erkennt man daran, dass man den Kaffee noch austrinken darf.", "You recognise a good connection by whether you can finish your coffee first.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-106", JourneyContentKind.SATIRE, "Wetterbedingte Verzögerung: Wenn sogar die Wolken am Fahrplan mitarbeiten.", "Weather-related delay: when even the clouds help write the timetable.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-107", JourneyContentKind.SATIRE, "Die vier natürlichen Feinde des Bahnfahrplans sind vermutlich die Jahreszeiten.", "The timetable's four natural enemies are probably the seasons.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-108", JourneyContentKind.SATIRE, "Ein Blatt auf der Schiene hat mehr Einfluss auf meinen Tag als mein Kalender.", "A leaf on the track has more influence on my day than my calendar does.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-109", JourneyContentKind.SATIRE, "Im Herbst wird aus einem Baum ein sehr stiller Verkehrsplaner.", "In autumn, a tree becomes a very quiet traffic planner.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-110", JourneyContentKind.SATIRE, "Der Sommer dehnt die Schienen. Der Winter dehnt die Geduld. Die Übergangszeit übt beides.", "Summer stretches the rails. Winter stretches patience. The seasons between practise both.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-111", JourneyContentKind.SATIRE, "Meine Regenjacke hat mehr Fahrten gerettet als jede optimistische Wetter-App.", "My raincoat has saved more journeys than any optimistic weather app.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-112", JourneyContentKind.SATIRE, "Die Sonne geht pünktlich auf. Sie ist offenbar nicht vom Schienenersatzverkehr abhängig.", "The Sun rises on time. Apparently it does not depend on replacement buses.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-113", JourneyContentKind.SATIRE, "Bei Nebel erkennt man die Verspätung erst, wenn man lange genug wartet.", "In fog, you only recognise a delay after waiting long enough.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-114", JourneyContentKind.SATIRE, "Wenn das Wetter umschlägt, hoffe ich wenigstens auf keinen Gleiswechsel der Wolken.", "When the weather turns, I just hope the clouds do not change platforms too.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-115", JourneyContentKind.SATIRE, "Mein Schirm fährt immer dann mit, wenn der Wetterbericht noch verhandelt.", "My umbrella travels whenever the forecast is still negotiating.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-116", JourneyContentKind.SATIRE, "Die Bahn hat mich spontan gemacht. Mein Kalender vermisst mein früheres Ich.", "The railway has made me spontaneous. My calendar misses the old me.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-117", JourneyContentKind.SATIRE, "Ich bin ein entspannter Mensch. Das wurde auf mehreren Bahnsteigen geprüft.", "I am a relaxed person. This has been tested on several platforms.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-118", JourneyContentKind.SATIRE, "Bahnhöfe sind die einzigen Orte, an denen ich freiwillig auf eine zweistellige Zahl starre.", "Stations are the only places where I willingly stare at a two-digit number.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-119", JourneyContentKind.SATIRE, "Mein Reisebudget enthält inzwischen einen Posten für ungeplante Bahnhofssnacks.", "My travel budget now has a category for unplanned station snacks.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-120", JourneyContentKind.SATIRE, "Ich kenne das Wort voraussichtlich inzwischen in allen emotionalen Abstufungen.", "I now know the word estimated in every emotional shade.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-121", JourneyContentKind.SATIRE, "Die Durchsage beginnt mit liebe Fahrgäste. Eine Beziehung mit wechselhafter Dramaturgie.", "The announcement begins dear passengers. A relationship with an unpredictable plot.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-122", JourneyContentKind.SATIRE, "Die Bahn macht aus Fremden eine Gruppe: Alle schauen gleichzeitig auf dieselbe Uhr.", "The railway turns strangers into a group: everyone looks at the same clock together.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-123", JourneyContentKind.SATIRE, "Mein Talent ist es, kurz vor der Durchsage die Kopfhörer wieder aufzusetzen.", "My talent is putting my headphones back on just before an announcement.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-124", JourneyContentKind.SATIRE, "Auf einer Bahnfahrt lernt man Geduld, Geografie und die Öffnungszeiten des Bahnhofskiosks.", "A train journey teaches patience, geography and the station kiosk's opening hours.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-125", JourneyContentKind.SATIRE, "Ich brauche keinen Escape Room. Ein unbekannter Bahnhof mit knapper Umstiegszeit genügt.", "I do not need an escape room. An unfamiliar station with a tight connection will do.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-126", JourneyContentKind.SATIRE, "Der Fahrplan hat Struktur. Die Reise hat Charakter.", "The timetable has structure. The journey has character.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-127", JourneyContentKind.SATIRE, "Die romantischste Bahnhofsgeste: jemand hält dir einen Platz frei, nicht den ganzen Zug.", "The most romantic station gesture: someone saves you a seat, not the whole train.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-128", JourneyContentKind.SATIRE, "Mein innerer Frieden reist mit Flexpreis.", "My inner peace travels on a flexible ticket.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-129", JourneyContentKind.SATIRE, "Ich bin nicht ungeduldig. Ich höre nur sehr aufmerksam auf alles, was nach Zug klingt.", "I am not impatient. I just listen very closely to anything that sounds like a train.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-130", JourneyContentKind.SATIRE, "Die Deutsche Bahn ist ein guter Gesprächseinstieg. Man muss nur gemeinsam warten.", "Deutsche Bahn is a good conversation starter. You only have to wait together.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-131", JourneyContentKind.SATIRE, "Eine Steckdose im Zug ist ein erstaunlich überzeugendes Ausflugsziel.", "A power socket on a train makes a surprisingly persuasive destination.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-132", JourneyContentKind.SATIRE, "Die Türtaste leuchtet. Für einen kurzen Moment fühlt sich Reiseplanung beherrschbar an.", "The door button lights up. For one brief moment, travel planning feels manageable.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-133", JourneyContentKind.SATIRE, "Das Zug-WLAN und ich schätzen unsere gemeinsame Zeit. Besonders die drei Sekunden am Stück.", "The train Wi-Fi and I treasure our time together. Especially those three uninterrupted seconds.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-134", JourneyContentKind.SATIRE, "Mein Koffer passt genau in die Ablage. Die Physik hat lediglich noch Einwände.", "My suitcase fits the luggage rack perfectly. Physics just has a few objections.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-135", JourneyContentKind.SATIRE, "Die automatische Tür erkennt mich. Mein Anschluss arbeitet noch daran.", "The automatic door recognises me. My connection is still working on it.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-136", JourneyContentKind.SATIRE, "Eine Durchsage mitten im Lieblingslied ist der persönliche Remix der Bahn.", "An announcement in the middle of a favourite song is the railway's personal remix.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-137", JourneyContentKind.SATIRE, "Ein Bahnsteigdach endet grundsätzlich dort, wo der Wind seine Arbeit beginnt.", "A platform roof always ends exactly where the wind gets to work.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-138", JourneyContentKind.SATIRE, "Mein Fahrrad reist mit. Die Suche nach seinem Stellplatz hat eine eigene Dramaturgie.", "My bicycle is coming too. Finding its space has a plot all of its own.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-139", JourneyContentKind.SATIRE, "Die Fahrkartenkontrolle findet mein Ticket schneller als ich meinen Bildschirm heller bekomme.", "The ticket inspector finds my ticket faster than I can turn up my screen brightness.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-140", JourneyContentKind.SATIRE, "Die schönste Durchsage bleibt die, nach der man entspannt sitzen bleiben kann.", "The loveliest announcement is still the one after which you can calmly stay seated.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("facts-041", JourneyContentKind.FACT, "San Franciscos erste Cable-Car-Testfahrt startete am 2. August 1873 um vier Uhr morgens.", "San Francisco's first cable car test started at four in the morning on 2 August 1873.", "https://www.sfmta.com/getting-around/muni/cable-cars/cable-car-history", null, "2026-10-28"),
    JourneyContent("facts-042", JourneyContentKind.FACT, "Die Clay Street Hill Railroad nahm ihren öffentlichen Cable-Car-Betrieb am 1. September 1873 auf.", "The Clay Street Hill Railroad began public cable car service on 1 September 1873.", "https://www.sfmta.com/getting-around/muni/cable-cars/cable-car-history", null, "2026-10-28"),
    JourneyContent("facts-043", JourneyContentKind.FACT, "Andrew Hallidie übertrug Seiltechnik aus dem Bergbau auf San Franciscos steile Stadtstraßen.", "Andrew Hallidie adapted mining cable technology to San Francisco's steep city streets.", "https://www.sfmta.com/getting-around/muni/cable-cars/cable-car-history", null, "2026-10-28"),
    JourneyContent("facts-044", JourneyContentKind.FACT, "San Franciscos historische Cable-Car-Unternehmen verlegten zusammen rund 53 Meilen Gleis.", "San Francisco's historic cable car companies laid about 53 miles of track combined.", "https://www.sfmta.com/getting-around/muni/cable-cars/cable-car-history", null, "2026-10-28"),
    JourneyContent("facts-045", JourneyContentKind.FACT, "Der geplante Start der ersten Cable-Car-Linie wurde 1873 um einen Tag verpasst.", "The first cable car line missed its planned opening in 1873 by one day.", "https://www.sfmta.com/getting-around/muni/cable-cars/cable-car-history", null, "2026-10-28"),
    JourneyContent("facts-046", JourneyContentKind.FACT, "Unter San Franciscos Cable-Car-Straßen bewegen sich vier Seilschleifen mit konstant 9,5 Meilen pro Stunde.", "Four cable loops beneath San Francisco's streets move at a constant 9.5 miles per hour.", "https://www.cablecarmuseum.org/archive/Anat/Anat.html", null, "2026-10-28"),
    JourneyContent("facts-047", JourneyContentKind.FACT, "Ein Cable Car fährt an, indem seine Greifzange das laufende Seil unter der Straße festhält.", "A cable car starts by gripping the moving cable beneath the street.", "https://www.cablecarmuseum.org/archive/Anat/Anat.html", null, "2026-10-28"),
    JourneyContent("facts-048", JourneyContentKind.FACT, "Die Antriebsmaschinen der Cable Cars stehen zentral im Maschinenhaus an Washington und Mason Street.", "The cable cars' drive machinery sits centrally at the Washington and Mason Street powerhouse.", "https://www.cablecarmuseum.org/archive/Anat/Anat.html", null, "2026-10-28"),
    JourneyContent("facts-049", JourneyContentKind.FACT, "Am Linienende läuft das Cable-Car-Seil um eine große Umlenkrolle, auf Englisch „sheave“.", "At the line's end, the cable runs around a large wheel called a sheave.", "https://www.cablecarmuseum.org/archive/Anat/Anat.html", null, "2026-10-28"),
    JourneyContent("facts-050", JourneyContentKind.FACT, "Im Cable Car Museum können Besucher die Maschinen beobachten, die gleichzeitig echte Fahrzeuge antreiben.", "Visitors to the Cable Car Museum can watch machinery that powers real vehicles at the same time.", "https://www.cablecarmuseum.org/archive/Anat/Anat.html", null, "2026-10-28"),
    JourneyContent("facts-051", JourneyContentKind.FACT, "San Franciscos früher Nahverkehr begann 1851 mit Pferdeomnibussen zwischen Portsmouth Square und Mission Dolores.", "San Francisco's early public transit began in 1851 with horse buses between Portsmouth Square and Mission Dolores.", "https://www.sfmta.com/getting-around/muni/muni-history", null, "2026-10-28"),
    JourneyContent("facts-052", JourneyContentKind.FACT, "Muni eröffnete am 28. Dezember 1912 mit Straßenbahnen auf den Linien A und B entlang der Geary Street.", "Muni opened on 28 December 1912 with streetcars on routes A and B along Geary Street.", "https://www.sfmta.com/getting-around/muni/muni-history", null, "2026-10-28"),
    JourneyContent("facts-053", JourneyContentKind.FACT, "Die Schriftstellerin Maya Angelou arbeitete 1944 kurz als Schaffnerin bei San Franciscos Market Street Railway.", "Writer Maya Angelou briefly worked as a conductor for San Francisco's Market Street Railway in 1944.", "https://www.sfmta.com/getting-around/muni/muni-history", null, "2026-10-28"),
    JourneyContent("facts-054", JourneyContentKind.FACT, "Friedel Klussmann mobilisierte 1947 eine Bürgerinitiative, die für den Erhalt der Cable Cars kämpfte.", "In 1947, Friedel Klussmann rallied a citizens' committee to preserve the cable cars.", "https://www.sfmta.com/getting-around/muni/muni-history", null, "2026-10-28"),
    JourneyContent("facts-055", JourneyContentKind.FACT, "San Francisco beschloss 1973, öffentlichen Verkehrsmitteln auf den Straßen Vorrang einzuräumen.", "In 1973, San Francisco adopted a policy giving public transport priority on its streets.", "https://www.sfmta.com/getting-around/muni/muni-history", null, "2026-10-28"),
    JourneyContent("facts-056", JourneyContentKind.FACT, "Glasgows Subway eröffnete am 14. Dezember 1896 als drittälteste U-Bahn nach London und Budapest.", "Glasgow's Subway opened on 14 December 1896, the third oldest after London and Budapest.", "https://www.spt.co.uk/125/", null, "2026-10-28"),
    JourneyContent("facts-057", JourneyContentKind.FACT, "Die ersten Glasgower U-Bahn-Züge wurden von Seilen gezogen; stationäre Dampfmaschinen lieferten die Kraft.", "Glasgow's first subway trains were cable hauled, with stationary steam engines providing power.", "https://www.spt.co.uk/125/", null, "2026-10-28"),
    JourneyContent("facts-058", JourneyContentKind.FACT, "Schon in der ersten Betriebsstunde nutzten 1896 etwa 1.400 Menschen Glasgows Subway.", "About 1,400 people used Glasgow's Subway in its first operating hour in 1896.", "https://www.spt.co.uk/125/", null, "2026-10-28"),
    JourneyContent("facts-059", JourneyContentKind.FACT, "1935 wurde Glasgows ursprünglich seilbetriebene Subway elektrifiziert.", "Glasgow's originally cable-hauled Subway was electrified in 1935.", "https://www.spt.co.uk/125/", null, "2026-10-28"),
    JourneyContent("facts-060", JourneyContentKind.FACT, "Nach einer dreijährigen Modernisierung öffnete Glasgows Subway 1980 wieder.", "Glasgow's Subway reopened in 1980 after a three-year modernisation.", "https://www.spt.co.uk/125/", null, "2026-10-28"),
    JourneyContent("facts-061", JourneyContentKind.FACT, "Lissabons Metro eröffnete am 29. Dezember 1959 mit einer Y-förmigen Strecke.", "Lisbon's metro opened on 29 December 1959 with a Y-shaped route.", "https://www.metrolisboa.pt/institucional/conhecer/historia-do-metro/", null, "2026-10-28"),
    JourneyContent("facts-062", JourneyContentKind.FACT, "Die Bauarbeiten für Lissabons erste Metro begannen im August 1955, vier Jahre vor der Eröffnung.", "Construction of Lisbon's first metro began in August 1955, four years before opening.", "https://www.metrolisboa.pt/institucional/conhecer/historia-do-metro/", null, "2026-10-28"),
    JourneyContent("facts-063", JourneyContentKind.FACT, "Lissabons frühe Metrozweige trafen sich an der damaligen Station Rotunda, heute Marquês de Pombal.", "Lisbon's early metro branches met at Rotunda station, now Marquês de Pombal.", "https://www.metrolisboa.pt/institucional/conhecer/historia-do-metro/", null, "2026-10-28"),
    JourneyContent("facts-064", JourneyContentKind.FACT, "Lissabons rote Linie wurde 1998 zur Expo eröffnet und erschloss das Ausstellungsgelände über Oriente.", "Lisbon's Red Line opened in 1998 for Expo, serving the exhibition area through Oriente.", "https://www.metrolisboa.pt/institucional/conhecer/historia-do-metro/", null, "2026-10-28"),
    JourneyContent("facts-065", JourneyContentKind.FACT, "Seit der Verlängerung von 2012 verbindet Lissabons rote Metrolinie Oriente mit dem Flughafen.", "Since the 2012 extension, Lisbon's Red Line has connected Oriente with the airport.", "https://www.metrolisboa.pt/institucional/conhecer/historia-do-metro/", null, "2026-10-28"),
    JourneyContent("facts-066", JourneyContentKind.FACT, "Tokios erste U-Bahn-Strecke eröffnete am 30. Dezember 1927 zwischen Asakusa und Ueno.", "Tokyo's first subway section opened between Asakusa and Ueno on 30 December 1927.", "https://www.tokyometro.jp/lang_en/corporate/profile/history/index.html", null, "2026-10-28"),
    JourneyContent("facts-067", JourneyContentKind.FACT, "Die Gesellschaft für Tokios erste U-Bahn wurde schon 1920 gegründet, sieben Jahre vor dem Fahrgastbetrieb.", "The company behind Tokyo's first subway was founded in 1920, seven years before passenger service.", "https://www.tokyometro.jp/lang_en/corporate/profile/history/index.html", null, "2026-10-28"),
    JourneyContent("facts-068", JourneyContentKind.FACT, "Seit 1939 verband ein durchgehender Zugbetrieb die zunächst getrennten U-Bahn-Gesellschaften zwischen Asakusa und Shibuya.", "Through trains connected the initially separate subway companies between Asakusa and Shibuya from 1939.", "https://www.tokyometro.jp/lang_en/corporate/profile/history/index.html", null, "2026-10-28"),
    JourneyContent("facts-069", JourneyContentKind.FACT, "Tokios Marunouchi-Linie startete 1954 auf dem Abschnitt Ikebukuro–Ochanomizu.", "Tokyo's Marunouchi Line began on the Ikebukuro–Ochanomizu section in 1954.", "https://www.tokyometro.jp/lang_en/corporate/profile/history/index.html", null, "2026-10-28"),
    JourneyContent("facts-070", JourneyContentKind.FACT, "1962 nahm die Hibiya-Linie den durchgehenden Betrieb mit der Tobu-Isesaki-Bahn auf.", "In 1962, the Hibiya Line began through service with the Tobu Isesaki railway.", "https://www.tokyometro.jp/lang_en/corporate/profile/history/index.html", null, "2026-10-28"),
    JourneyContent("facts-071", JourneyContentKind.FACT, "Tokios erste U-Bahn verband 1927 Asakusa und Ueno auf einer nur 2,2 Kilometer langen Strecke.", "Tokyo's first subway connected Asakusa and Ueno over just 2.2 kilometres in 1927.", "https://www.tokyometro.jp/corporate/csr/report/pdf/sr2024_en.pdf", null, "2026-10-28"),
    JourneyContent("facts-072", JourneyContentKind.FACT, "Tokios U-Bahn setzte bereits 1943 Frauen als Schaffnerinnen und 1944 als Fahrerinnen ein.", "Tokyo's subway appointed female conductors in 1943 and female drivers in 1944.", "https://www.tokyometro.jp/corporate/csr/report/pdf/sr2024_en.pdf", null, "2026-10-28"),
    JourneyContent("facts-073", JourneyContentKind.FACT, "Tokios Tozai-Linie wurde 1969 vollständig eröffnet; im selben Jahr überschritt das damalige Netz 100 Kilometer.", "Tokyo's Tozai Line fully opened in 1969, when the then network also exceeded 100 kilometres.", "https://www.tokyometro.jp/corporate/csr/report/pdf/sr2024_en.pdf", null, "2026-10-28"),
    JourneyContent("facts-074", JourneyContentKind.FACT, "1988 wurde das Rauchen in sämtlichen Stationen der damaligen Teito-U-Bahn verboten.", "Smoking was banned throughout all stations of the then Teito subway in 1988.", "https://www.tokyometro.jp/corporate/csr/report/pdf/sr2024_en.pdf", null, "2026-10-28"),
    JourneyContent("facts-075", JourneyContentKind.FACT, "Mit der 2008 eröffneten Fukutoshin-Linie erreichte Tokyo Metro sein Netz aus neun Linien.", "The Fukutoshin Line opening in 2008 completed Tokyo Metro's nine-line network.", "https://www.tokyometro.jp/corporate/csr/report/pdf/sr2024_en.pdf", null, "2026-10-28"),
    JourneyContent("facts-076", JourneyContentKind.FACT, "Kopenhagens Metro startete am 19. Oktober 2002 mit den Linien M1 und M2.", "Copenhagen's metro started with lines M1 and M2 on 19 October 2002.", "https://metroselskabet.dk/en/contact-and-press/press/press-releases/20-years-of-the-metro-has-transformed-the-capital-from-metropolis-to-metropolis/", null, "2026-10-28"),
    JourneyContent("facts-077", JourneyContentKind.FACT, "Bereits 1902 wurde in Kopenhagen über eine Metro nachgedacht – ein Jahrhundert vor ihrer Eröffnung.", "Copenhagen considered a metro as early as 1902, a century before it opened.", "https://metroselskabet.dk/en/contact-and-press/press/press-releases/20-years-of-the-metro-has-transformed-the-capital-from-metropolis-to-metropolis/", null, "2026-10-28"),
    JourneyContent("facts-078", JourneyContentKind.FACT, "Kopenhagens M2 wurde 2007 bis zum Flughafen verlängert.", "Copenhagen's M2 was extended to the airport in 2007.", "https://metroselskabet.dk/en/contact-and-press/press/press-releases/20-years-of-the-metro-has-transformed-the-capital-from-metropolis-to-metropolis/", null, "2026-10-28"),
    JourneyContent("facts-079", JourneyContentKind.FACT, "Seit 2009 fährt Kopenhagens Metro rund um die Uhr an allen sieben Wochentagen.", "Copenhagen's metro has operated around the clock, seven days a week, since 2009.", "https://metroselskabet.dk/en/contact-and-press/press/press-releases/20-years-of-the-metro-has-transformed-the-capital-from-metropolis-to-metropolis/", null, "2026-10-28"),
    JourneyContent("facts-080", JourneyContentKind.FACT, "2019 bekam Kopenhagen mit der M3 eine neue Metro-Ringlinie namens Cityringen.", "In 2019, Copenhagen gained a new metro circle line, the M3 Cityringen.", "https://metroselskabet.dk/en/contact-and-press/press/press-releases/20-years-of-the-metro-has-transformed-the-capital-from-metropolis-to-metropolis/", null, "2026-10-28"),
    JourneyContent("facts-081", JourneyContentKind.FACT, "Auch fahrerlose Metrozüge können von Personal manuell gefahren werden: Kopenhagens Stewards sind dafür ausgebildet.", "Even driverless metro trains can be driven manually: Copenhagen's stewards are trained to do so.", "https://metroservice.dk/en/what-we-do/the-metro/", null, "2026-10-28"),
    JourneyContent("facts-082", JourneyContentKind.FACT, "Kopenhagens M1 und M2 werden aus einem Kontrollzentrum zwischen Ørestad und Vestamager überwacht.", "Copenhagen's M1 and M2 are monitored from a control centre between Ørestad and Vestamager.", "https://metroservice.dk/en/what-we-do/the-metro/", null, "2026-10-28"),
    JourneyContent("facts-083", JourneyContentKind.FACT, "Für Kopenhagens M3 und M4 gibt es ein eigenes Kontroll- und Wartungszentrum in Sydhavn.", "Copenhagen's M3 and M4 have a separate control and maintenance centre in Sydhavn.", "https://metroservice.dk/en/what-we-do/the-metro/", null, "2026-10-28"),
    JourneyContent("facts-084", JourneyContentKind.FACT, "Kopenhagens M4 nahm 2020 den Betrieb nach Orientkaj im Nordhafen auf.", "Copenhagen's M4 began operating to Orientkaj in the north harbour in 2020.", "https://metroservice.dk/en/what-we-do/the-metro/", null, "2026-10-28"),
    JourneyContent("facts-085", JourneyContentKind.FACT, "2024 wurde Kopenhagens M4 weiter bis København Syd verlängert.", "In 2024, Copenhagen's M4 was extended further to København Syd.", "https://metroservice.dk/en/what-we-do/the-metro/", null, "2026-10-28"),
    JourneyContent("facts-086", JourneyContentKind.FACT, "Hongkongs MTR startete am 1. Oktober 1979 zwischen Kwun Tong und Shek Kip Mei.", "Hong Kong's MTR started between Kwun Tong and Shek Kip Mei on 1 October 1979.", "https://www.mtr.com.hk/en/corporate/images/investor/2014frpt/EMTRAR2014F.pdf", null, "2026-10-28"),
    JourneyContent("facts-087", JourneyContentKind.FACT, "Am ersten Betriebstag 1979 beförderte Hongkongs neues MTR-System rund 285.000 Fahrgäste.", "Hong Kong's new MTR carried about 285,000 passengers on its first operating day in 1979.", "https://www.mtr.com.hk/en/corporate/images/investor/2014frpt/EMTRAR2014F.pdf", null, "2026-10-28"),
    JourneyContent("facts-088", JourneyContentKind.FACT, "Hongkongs Island Line eröffnete 1985 zunächst zwischen Chai Wan und Admiralty.", "Hong Kong's Island Line initially opened between Chai Wan and Admiralty in 1985.", "https://www.mtr.com.hk/en/corporate/images/investor/2014frpt/EMTRAR2014F.pdf", null, "2026-10-28"),
    JourneyContent("facts-089", JourneyContentKind.FACT, "Der östliche Eisenbahntunnel unter Hongkongs Victoria Harbour wurde 1989 eröffnet.", "Hong Kong's eastern railway crossing beneath Victoria Harbour opened in 1989.", "https://www.mtr.com.hk/en/corporate/images/investor/2014frpt/EMTRAR2014F.pdf", null, "2026-10-28"),
    JourneyContent("facts-090", JourneyContentKind.FACT, "Hongkongs Airport Express nahm am 6. Juli 1998 den Betrieb zum neuen Flughafen auf.", "Hong Kong's Airport Express began operating to the new airport on 6 July 1998.", "https://www.mtr.com.hk/en/corporate/images/investor/2014frpt/EMTRAR2014F.pdf", null, "2026-10-28"),
    JourneyContent("facts-091", JourneyContentKind.FACT, "Hongkongs Octopus-System startete im September 1997: Eine kontaktlose Karte verband mehrere Verkehrsmittel.", "Hong Kong's Octopus system launched in September 1997, linking multiple transport modes with one contactless card.", "https://www.octopus.com.hk/en/corporate/about-octopus/profile/overview/index.html", null, "2026-10-28"),
    JourneyContent("facts-092", JourneyContentKind.FACT, "Hinter der Octopus-Karte stand eine 1994 gegründete Kooperation von fünf großen Verkehrsunternehmen.", "The Octopus card grew from a partnership of five major transport operators formed in 1994.", "https://www.octopus.com.hk/en/corporate/about-octopus/profile/overview/index.html", null, "2026-10-28"),
    JourneyContent("facts-093", JourneyContentKind.FACT, "Zu den Gründern des Octopus-Vorgängers gehörte neben Bahn- und Busunternehmen auch eine Fährgesellschaft.", "Alongside rail and bus companies, a ferry operator helped found the predecessor of Octopus.", "https://www.octopus.com.hk/en/corporate/about-octopus/profile/overview/index.html", null, "2026-10-28"),
    JourneyContent("facts-094", JourneyContentKind.FACT, "Die Einführung von Octopus ersparte Hongkongs Fahrgästen die Suche nach passendem Kleingeld.", "The introduction of Octopus saved Hong Kong passengers from finding exact change.", "https://www.octopus.com.hk/en/corporate/about-octopus/profile/overview/index.html", null, "2026-10-28"),
    JourneyContent("facts-095", JourneyContentKind.FACT, "Die spätere Octopus Cards Limited hieß bei ihrer Gründung zunächst Creative Star Limited.", "The company later called Octopus Cards Limited was originally named Creative Star Limited.", "https://www.octopus.com.hk/en/corporate/about-octopus/profile/overview/index.html", null, "2026-10-28"),
    JourneyContent("facts-096", JourneyContentKind.FACT, "BARTs Transbay Tube öffnete am 16. September 1974 für Fahrgäste zwischen Oakland und San Francisco.", "BART's Transbay Tube opened to passengers between Oakland and San Francisco on 16 September 1974.", "https://www.bart.gov/news/articles/2024/news20240916", null, "2026-10-28"),
    JourneyContent("facts-097", JourneyContentKind.FACT, "BARTs Transbay Tube ist ein Absenktunnel: Vorgefertigte Elemente wurden auf dem Grund der Bucht platziert.", "BART's Transbay Tube is an immersed tunnel, assembled from prefabricated elements placed on the bay floor.", "https://www.bart.gov/news/articles/2024/news20240916", null, "2026-10-28"),
    JourneyContent("facts-098", JourneyContentKind.FACT, "Taucher halfen dabei, die Elemente der Transbay Tube unter Wasser genau auszurichten.", "Divers helped align the Transbay Tube's elements precisely underwater.", "https://www.bart.gov/news/articles/2024/news20240916", null, "2026-10-28"),
    JourneyContent("facts-099", JourneyContentKind.FACT, "Laser von verschiedenen Uferpunkten sicherten die genaue Lage des ausgebaggerten Grabens für BARTs Tunnel.", "Lasers from different shore positions guided the precise dredging of the trench for BART's tunnel.", "https://www.bart.gov/news/articles/2024/news20240916", null, "2026-10-28"),
    JourneyContent("facts-100", JourneyContentKind.FACT, "1969 konnten Besucher Teile der Transbay Tube zu Fuß besichtigen, fünf Jahre vor dem Fahrgastbetrieb.", "In 1969, visitors could walk through parts of the Transbay Tube, five years before passenger service.", "https://www.bart.gov/news/articles/2024/news20240916", null, "2026-10-28"),
    JourneyContent("facts-101", JourneyContentKind.FACT, "Torontos erste U-Bahn-Strecke zwischen Eglinton und Union eröffnete am 30. März 1954.", "Toronto's first subway section between Eglinton and Union opened on 30 March 1954.", "https://www.ttc.ca/transparency-and-accountability/Operating-Statistics/Operating-Statistics---2025/Official-Opening-Dates", null, "2026-10-28"),
    JourneyContent("facts-102", JourneyContentKind.FACT, "Torontos University Subway eröffnete 1963 zwischen Union und St George.", "Toronto's University Subway opened between Union and St George in 1963.", "https://www.ttc.ca/transparency-and-accountability/Operating-Statistics/Operating-Statistics---2025/Official-Opening-Dates", null, "2026-10-28"),
    JourneyContent("facts-103", JourneyContentKind.FACT, "Die Bloor-Danforth-Strecke der Torontoer U-Bahn startete 1966 zwischen Keele und Woodbine.", "Toronto's Bloor-Danforth subway started between Keele and Woodbine in 1966.", "https://www.ttc.ca/transparency-and-accountability/Operating-Statistics/Operating-Statistics---2025/Official-Opening-Dates", null, "2026-10-28"),
    JourneyContent("facts-104", JourneyContentKind.FACT, "1978 eröffnete in Toronto die Spadina-U-Bahn von St George bis Wilson.", "Toronto's Spadina subway opened from St George to Wilson in 1978.", "https://www.ttc.ca/transparency-and-accountability/Operating-Statistics/Operating-Statistics---2025/Official-Opening-Dates", null, "2026-10-28"),
    JourneyContent("facts-105", JourneyContentKind.FACT, "1980 erreichte Torontos Bloor-Danforth-U-Bahn die Stationen Kipling und Kennedy.", "Toronto's Bloor-Danforth subway reached Kipling and Kennedy stations in 1980.", "https://www.ttc.ca/transparency-and-accountability/Operating-Statistics/Operating-Statistics---2025/Official-Opening-Dates", null, "2026-10-28"),
    JourneyContent("facts-106", JourneyContentKind.FACT, "Die Toronto Transportation Commission nahm am 1. September 1921 ihren Betrieb auf.", "The Toronto Transportation Commission began operating on 1 September 1921.", "https://www.ttc.ca/news/2011/September/TTC-marks-its-90th-anniversary-Sept-1", null, "2026-10-28"),
    JourneyContent("facts-107", JourneyContentKind.FACT, "Bei ihrer Gründung 1921 übernahm die TTC private und städtische Straßenbahnbetriebe unter einem Dach.", "At its founding in 1921, the TTC brought private and municipal streetcar operations together.", "https://www.ttc.ca/news/2011/September/TTC-marks-its-90th-anniversary-Sept-1", null, "2026-10-28"),
    JourneyContent("facts-108", JourneyContentKind.FACT, "Der erste TTC-Erwachsenenfahrpreis betrug 1921 sieben Cent; vier Fahrkarten kosteten 25 Cent.", "The TTC's initial adult fare in 1921 was seven cents, or four tickets for 25 cents.", "https://www.ttc.ca/news/2011/September/TTC-marks-its-90th-anniversary-Sept-1", null, "2026-10-28"),
    JourneyContent("facts-109", JourneyContentKind.FACT, "Torontos frühe TTC-Buslinien waren als Zubringer zu stärker genutzten Straßenbahnlinien gedacht.", "Toronto's early TTC bus routes were designed as feeders to busier streetcar routes.", "https://www.ttc.ca/news/2011/September/TTC-marks-its-90th-anniversary-Sept-1", null, "2026-10-28"),
    JourneyContent("facts-110", JourneyContentKind.FACT, "1921 erhielt Toronto neue Peter-Witt-Straßenbahnen mit Stahlwagenkästen.", "In 1921, Toronto received new Peter Witt streetcars with steel bodies.", "https://www.ttc.ca/news/2011/September/TTC-marks-its-90th-anniversary-Sept-1", null, "2026-10-28"),
    JourneyContent("facts-111", JourneyContentKind.FACT, "Die Pariser Métrolinie 1 eröffnete am 19. Juli 1900 zwischen Porte Maillot und Porte de Vincennes.", "Paris metro Line 1 opened between Porte Maillot and Porte de Vincennes on 19 July 1900.", "https://www.ratp.fr/125-ans-metro", null, "2026-10-28"),
    JourneyContent("facts-112", JourneyContentKind.FACT, "Die erste Pariser Métro sollte wichtige Standorte der Weltausstellung von 1900 miteinander verbinden.", "The first Paris metro was intended to connect important sites of the 1900 World Fair.", "https://www.ratp.fr/125-ans-metro", null, "2026-10-28"),
    JourneyContent("facts-113", JourneyContentKind.FACT, "1956 begann auf der Pariser Linie 11 der Fahrgastbetrieb mit gummibereiften Métrozügen.", "In 1956, rubber-tyred metro trains entered passenger service on Paris Line 11.", "https://www.ratp.fr/125-ans-metro", null, "2026-10-28"),
    JourneyContent("facts-114", JourneyContentKind.FACT, "Die erste Klasse verschwand 1991 aus der Pariser Métro, im RER erst 1999.", "First class disappeared from the Paris metro in 1991, but from the RER only in 1999.", "https://www.ratp.fr/125-ans-metro", null, "2026-10-28"),
    JourneyContent("facts-115", JourneyContentKind.FACT, "Die historischen Sprague-Thomson-Züge beendeten ihren regulären Pariser Métrobetrieb am 16. April 1983.", "Historic Sprague-Thomson trains ended regular Paris metro service on 16 April 1983.", "https://www.ratp.fr/125-ans-metro", null, "2026-10-28"),
    JourneyContent("facts-116", JourneyContentKind.FACT, "Pariser Linie 14 eröffnete 1998 von Beginn an vollautomatisch zwischen Madeleine und Bibliothèque François Mitterrand.", "Paris Line 14 opened fully automated from the start in 1998, between Madeleine and Bibliothèque François Mitterrand.", "https://www.ratp.fr/decouvrir/patrimoine/histoire-metro-ligne-14", null, "2026-10-28"),
    JourneyContent("facts-117", JourneyContentKind.FACT, "Der Projektname Météor der Pariser Linie 14 steht für „Métro Est-Ouest Rapide“.", "The project name Météor for Paris Line 14 stands for Métro Est-Ouest Rapide.", "https://www.ratp.fr/decouvrir/patrimoine/histoire-metro-ligne-14", null, "2026-10-28"),
    JourneyContent("facts-118", JourneyContentKind.FACT, "Der Tunnelbohrer Sandrine baute für die Pariser Linie 14 einen 4.550 Meter langen zweigleisigen Tunnel.", "Tunnel boring machine Sandrine built a 4,550-metre twin-track tunnel for Paris Line 14.", "https://www.ratp.fr/decouvrir/patrimoine/histoire-metro-ligne-14", null, "2026-10-28"),
    JourneyContent("facts-119", JourneyContentKind.FACT, "Eine frühere Pariser Linie 14 verband von 1937 bis 1976 Invalides mit Porte de Vanves.", "An earlier Paris Line 14 connected Invalides with Porte de Vanves from 1937 to 1976.", "https://www.ratp.fr/decouvrir/patrimoine/histoire-metro-ligne-14", null, "2026-10-28"),
    JourneyContent("facts-120", JourneyContentKind.FACT, "Bahnsteigtüren gehörten bei den Stationen der neuen Pariser Linie 14 von Anfang an zum Gestaltungskonzept.", "Platform screen doors were part of the new Paris Line 14 stations' design from the beginning.", "https://www.ratp.fr/decouvrir/patrimoine/histoire-metro-ligne-14", null, "2026-10-28"),
    JourneyContent("facts-121", JourneyContentKind.FACT, "1969 eröffnete der erste RER-A-Abschnitt zwischen Nation und Boissy-Saint-Léger.", "The first RER A section opened between Nation and Boissy-Saint-Léger in 1969.", "https://www.iledefrance-mobilites.fr/decouvrir/histoire", null, "2026-10-28"),
    JourneyContent("facts-122", JourneyContentKind.FACT, "1975 kam in der Pariser Region die Carte Orange als gemeinsames Zeitkartenangebot auf den Markt.", "The Carte Orange season ticket was introduced in the Paris region in 1975.", "https://www.iledefrance-mobilites.fr/decouvrir/histoire", null, "2026-10-28"),
    JourneyContent("facts-123", JourneyContentKind.FACT, "1992 kehrte die Straßenbahn mit der T1 zwischen Bobigny und Saint-Denis in die Pariser Region zurück.", "Trams returned to the Paris region in 1992 with T1 between Bobigny and Saint-Denis.", "https://www.iledefrance-mobilites.fr/decouvrir/histoire", null, "2026-10-28"),
    JourneyContent("facts-124", JourneyContentKind.FACT, "Der RER E wurde 1999 mit dem Pariser Endpunkt Haussmann eröffnet.", "The RER E opened in 1999 with its Paris terminus at Haussmann.", "https://www.iledefrance-mobilites.fr/decouvrir/histoire", null, "2026-10-28"),
    JourneyContent("facts-125", JourneyContentKind.FACT, "Die ersten Navigo-Intégrale-Karten wurden 2001 in der Pariser Region eingeführt.", "The first Navigo Intégrale cards were introduced in the Paris region in 2001.", "https://www.iledefrance-mobilites.fr/decouvrir/histoire", null, "2026-10-28"),
    JourneyContent("facts-126", JourneyContentKind.FACT, "Die Darjeeling Himalayan Railway eröffnete 1881 und nutzt nur 610 Millimeter Spurweite.", "The Darjeeling Himalayan Railway opened in 1881 and uses a gauge of just 610 millimetres.", "https://whc.unesco.org/en/list/944/", null, "2026-10-28"),
    JourneyContent("facts-127", JourneyContentKind.FACT, "Die Darjeeling-Bahn überwindet das Gelände unter anderem mit sechs Spitzkehren und drei Schleifen.", "The Darjeeling railway tackles the terrain with six zigzag reverses and three loops.", "https://whc.unesco.org/en/list/944/", null, "2026-10-28"),
    JourneyContent("facts-128", JourneyContentKind.FACT, "Die Nilgiri Mountain Railway steigt von 326 auf 2.203 Meter Höhe und nutzt dafür Zahnstangentechnik.", "The Nilgiri Mountain Railway climbs from 326 to 2,203 metres, using rack-and-pinion traction.", "https://whc.unesco.org/en/list/944/", null, "2026-10-28"),
    JourneyContent("facts-129", JourneyContentKind.FACT, "Der Bau der Nilgiri-Bahn wurde 1854 vorgeschlagen, begann aber erst 1891 und endete 1908.", "The Nilgiri railway was proposed in 1854, but construction only began in 1891 and finished in 1908.", "https://whc.unesco.org/en/list/944/", null, "2026-10-28"),
    JourneyContent("facts-130", JourneyContentKind.FACT, "Das UNESCO-Welterbe „Mountain Railways of India“ umfasst Darjeeling, Nilgiri und Kalka-Shimla.", "The UNESCO World Heritage property Mountain Railways of India includes Darjeeling, Nilgiri and Kalka-Shimla.", "https://whc.unesco.org/en/list/944/", null, "2026-10-28"),
    JourneyContent("facts-131", JourneyContentKind.FACT, "Europas erste Berg-Zahnradbahn eröffnete am 21. Mai 1871 von Vitznau bis Rigi Staffelhöhe.", "Europe's first mountain rack railway opened from Vitznau to Rigi Staffelhöhe on 21 May 1871.", "https://www.rigi.ch/en/about-us/history/railway-history", null, "2026-10-28"),
    JourneyContent("facts-132", JourneyContentKind.FACT, "Die Eröffnung der Vitznau-Rigi-Bahn fiel auf den 54. Geburtstag ihres Ingenieurs Niklaus Riggenbach.", "The Vitznau-Rigi railway opened on engineer Niklaus Riggenbach's 54th birthday.", "https://www.rigi.ch/en/about-us/history/railway-history", null, "2026-10-28"),
    JourneyContent("facts-133", JourneyContentKind.FACT, "Riggenbach ließ sein Zahnradsystem für Bergbahnen 1863 in Frankreich patentieren.", "Riggenbach patented his mountain railway rack system in France in 1863.", "https://www.rigi.ch/en/about-us/history/railway-history", null, "2026-10-28"),
    JourneyContent("facts-134", JourneyContentKind.FACT, "Die Arth-Rigi-Bahn eröffnete 1875 als zweite große Bahnverbindung auf die Rigi.", "The Arth-Rigi railway opened in 1875 as a second major railway route up Mount Rigi.", "https://www.rigi.ch/en/about-us/history/railway-history", null, "2026-10-28"),
    JourneyContent("facts-135", JourneyContentKind.FACT, "1907 wurde die Arth-Rigi-Bahn zur ersten elektrifizierten normalspurigen Zahnradbahn der Welt.", "In 1907, the Arth-Rigi railway became the world's first electrified standard-gauge rack railway.", "https://www.rigi.ch/en/about-us/history/railway-history", null, "2026-10-28"),
    JourneyContent("facts-136", JourneyContentKind.FACT, "Die Pilatusbahn bewältigt maximal 48 Prozent Steigung – 48 Höhenmeter je 100 waagerechte Meter.", "The Pilatus Railway tackles a maximum 48 per cent gradient: 48 metres of rise per 100 horizontal metres.", "https://www.pilatus.ch/en/discover/cogwheel-railway", null, "2026-10-28"),
    JourneyContent("facts-137", JourneyContentKind.FACT, "Die Pilatusbahn eröffnete am 4. Juni 1889 mit Dampfbetrieb und wurde 1937 elektrifiziert.", "The Pilatus Railway opened with steam traction on 4 June 1889 and was electrified in 1937.", "https://www.pilatus.ch/en/discover/cogwheel-railway", null, "2026-10-28"),
    JourneyContent("facts-138", JourneyContentKind.FACT, "Auf 4.618 Metern Strecke überwindet die Pilatusbahn einen Höhenunterschied von 1.635 Metern.", "Over 4,618 metres of route, the Pilatus Railway climbs 1,635 vertical metres.", "https://www.pilatus.ch/en/discover/cogwheel-railway", null, "2026-10-28"),
    JourneyContent("facts-139", JourneyContentKind.FACT, "Das Locher-System der Pilatusbahn greift mit horizontal drehenden Zahnrädern seitlich in die Zahnstange.", "The Pilatus Railway's Locher system uses horizontally rotating cogwheels that engage the rack from the sides.", "https://www.pilatus.ch/en/discover/cogwheel-railway", null, "2026-10-28"),
    JourneyContent("facts-140", JourneyContentKind.FACT, "Die Spurweite der Pilatusbahn beträgt 800 Millimeter; ihre Oberleitung liefert 1.500 Volt Gleichstrom.", "The Pilatus Railway has an 800-millimetre gauge and overhead power at 1,500 volts DC.", "https://www.pilatus.ch/en/discover/cogwheel-railway", null, "2026-10-28"),
    JourneyContent("facts-141", JourneyContentKind.FACT, "Hamburg wurde 1912 nach Berlin zur zweiten deutschen Stadt mit einer U-Bahn.", "In 1912, Hamburg became Germany's second city with an underground railway, after Berlin.", "https://www.hochbahn.de/de/unternehmen/die-geschichte-der-hochbahn", null, "2026-10-28"),
    JourneyContent("facts-142", JourneyContentKind.FACT, "Die Hamburger Hoch- und Untergrundbahn entstand in nur sechs Jahren Bauzeit.", "Hamburg's elevated and underground railway was built in just six years.", "https://www.hochbahn.de/de/unternehmen/die-geschichte-der-hochbahn", null, "2026-10-28"),
    JourneyContent("facts-143", JourneyContentKind.FACT, "Die feierliche erste Fahrt auf Hamburgs Ringlinie fand am 15. Februar 1912 statt.", "The ceremonial first journey on Hamburg's circle line took place on 15 February 1912.", "https://www.hochbahn.de/de/unternehmen/die-geschichte-der-hochbahn", null, "2026-10-28"),
    JourneyContent("facts-144", JourneyContentKind.FACT, "Der fahrplanmäßige Hamburger U-Bahn-Verkehr begann im März 1912, nach der Eröffnungsfeier im Februar.", "Scheduled Hamburg underground service began in March 1912, following February's opening ceremony.", "https://www.hochbahn.de/de/unternehmen/die-geschichte-der-hochbahn", null, "2026-10-28"),
    JourneyContent("facts-145", JourneyContentKind.FACT, "Hamburgs erste U-Bahn-Strecke war als Ring angelegt, aus dem später weitere Zweige herauswuchsen.", "Hamburg's first underground route was a circle, from which further branches later grew.", "https://www.hochbahn.de/de/unternehmen/die-geschichte-der-hochbahn", null, "2026-10-28"),
    JourneyContent("facts-146", JourneyContentKind.FACT, "Hamburgs ursprünglicher U-Bahn-Ring besaß 23 Haltestellen und ein eigenes Kraftwerk in Barmbek.", "Hamburg's original underground circle had 23 stations and its own power station in Barmbek.", "https://www.hochbahn.de/de/unternehmen/die-geschichte-der-hochbahn/1900-1912-zeitreise-zu-hamburgs-erster-u-bahn", null, "2026-10-28"),
    JourneyContent("facts-147", JourneyContentKind.FACT, "Ein eigens angelegter Stichkanal versorgte Hamburgs frühes U-Bahn-Kraftwerk mit Kohle.", "A purpose-built canal supplied coal to Hamburg's early underground power station.", "https://www.hochbahn.de/de/unternehmen/die-geschichte-der-hochbahn/1900-1912-zeitreise-zu-hamburgs-erster-u-bahn", null, "2026-10-28"),
    JourneyContent("facts-148", JourneyContentKind.FACT, "Hamburgs frühe T-Wagen konnten mit 800 Volt Gleichstrom bis zu 60 km/h erreichen.", "Hamburg's early T cars could reach 60 km/h using 800 volts DC.", "https://www.hochbahn.de/de/unternehmen/die-geschichte-der-hochbahn/1900-1912-zeitreise-zu-hamburgs-erster-u-bahn", null, "2026-10-28"),
    JourneyContent("facts-149", JourneyContentKind.FACT, "Die Hamburger U-Bahn unterschied anfangs eine zweite und dritte Klasse; diese Trennung endete 1920.", "Hamburg's underground initially had second and third classes; that division ended in 1920.", "https://www.hochbahn.de/de/unternehmen/die-geschichte-der-hochbahn/1900-1912-zeitreise-zu-hamburgs-erster-u-bahn", null, "2026-10-28"),
    JourneyContent("facts-150", JourneyContentKind.FACT, "In bebauten Quartieren passten sich Hamburgs frühe U-Bahn-Stationen bewusst an die umgebende Architektur an.", "In built-up neighbourhoods, Hamburg's early underground stations deliberately matched the surrounding architecture.", "https://www.hochbahn.de/de/unternehmen/die-geschichte-der-hochbahn/1900-1912-zeitreise-zu-hamburgs-erster-u-bahn", null, "2026-10-28"),
    JourneyContent("facts-151", JourneyContentKind.FACT, "Prags erste Metro eröffnete am 9. Mai 1974 auf der Linie C zwischen Kačerov und Sokolovská.", "Prague's first metro opened on Line C between Kačerov and Sokolovská on 9 May 1974.", "https://www.dpp.cz/en/entertainment-and-experience/dpp-history/history-of-the-public-transport-in-prague", null, "2026-10-28"),
    JourneyContent("facts-152", JourneyContentKind.FACT, "Prags Metro ging aus Planungen für eine unterirdische Straßenbahn hervor; 1967 änderte sich das Konzept.", "Prague's metro grew out of plans for a subsurface tramway; the concept changed in 1967.", "https://www.dpp.cz/en/entertainment-and-experience/dpp-history/history-of-the-public-transport-in-prague", null, "2026-10-28"),
    JourneyContent("facts-153", JourneyContentKind.FACT, "Prags Metrolinie A startete 1978 zwischen Náměstí Míru und der heutigen Station Dejvická.", "Prague's metro Line A started in 1978 between Náměstí Míru and today's Dejvická station.", "https://www.dpp.cz/en/entertainment-and-experience/dpp-history/history-of-the-public-transport-in-prague", null, "2026-10-28"),
    JourneyContent("facts-154", JourneyContentKind.FACT, "Die Standseilbahn auf Prags Petřín kehrte 1985 nach zwanzig Jahren Pause und umfassender Erneuerung zurück.", "Prague's Petřín funicular returned in 1985 after a twenty-year closure and extensive renewal.", "https://www.dpp.cz/en/entertainment-and-experience/dpp-history/history-of-the-public-transport-in-prague", null, "2026-10-28"),
    JourneyContent("facts-155", JourneyContentKind.FACT, "Prags Metrolinie B eröffnete 1985 zunächst zwischen Smíchovské nádraží und der heutigen Station Florenc.", "Prague's metro Line B initially opened in 1985 between Smíchovské nádraží and today's Florenc station.", "https://www.dpp.cz/en/entertainment-and-experience/dpp-history/history-of-the-public-transport-in-prague", null, "2026-10-28"),
    JourneyContent("facts-156", JourneyContentKind.FACT, "Nürnbergs automatische U3 wurde am 14. Juni 2008 offiziell eröffnet.", "Nuremberg's automated U3 officially opened on 14 June 2008.", "https://blog.vag.de/einblick/automatisierung-von-u-bahnen-nuernberg-ist-gefragt/", null, "2026-10-28"),
    JourneyContent("facts-157", JourneyContentKind.FACT, "In Nürnberg teilten sich 2008 und 2009 fahrergesteuerte U2-Züge und automatische U3-Züge dieselbe Strecke.", "In Nuremberg in 2008 and 2009, manually driven U2 trains shared track with automated U3 trains.", "https://blog.vag.de/einblick/automatisierung-von-u-bahnen-nuernberg-ist-gefragt/", null, "2026-10-28"),
    JourneyContent("facts-158", JourneyContentKind.FACT, "Nürnbergs U2 wurde bis 2010 auf fahrerlosen Betrieb umgestellt, ohne den Betrieb dafür tageweise stillzulegen.", "Nuremberg's U2 converted to driverless operation by 2010 without requiring full-day closures for the conversion.", "https://blog.vag.de/einblick/automatisierung-von-u-bahnen-nuernberg-ist-gefragt/", null, "2026-10-28"),
    JourneyContent("facts-159", JourneyContentKind.FACT, "Münchens erste U-Bahn-Linie hieß U6 statt U1, weil sie einen Teil der Tramlinie 6 ersetzte.", "Munich's first underground line was called U6 rather than U1 because it replaced part of tram route 6.", "https://www.swm.de/unternehmen/magazin/leben/mvg-50-jahre-ubahn", null, "2026-10-28"),
    JourneyContent("facts-160", JourneyContentKind.FACT, "Münchens erste U-Bahn fuhr 1971 zwischen Kieferngarten und Goetheplatz.", "Munich's first underground ran between Kieferngarten and Goetheplatz in 1971.", "https://www.swm.de/unternehmen/magazin/leben/mvg-50-jahre-ubahn", null, "2026-10-28"),
    JourneyContent("facts-161", JourneyContentKind.FACT, "Die Münchner U3 eröffnete rechtzeitig zu den Olympischen Sommerspielen von 1972.", "Munich's U3 opened in time for the 1972 Summer Olympics.", "https://www.swm.de/unternehmen/magazin/leben/mvg-50-jahre-ubahn", null, "2026-10-28"),
    JourneyContent("facts-162", JourneyContentKind.FACT, "Ein Teil des späteren Münchner U-Bahn-Netzes begann 1938 als Bauprojekt für einen S-Bahn-Tunnel.", "Part of Munich's later underground network began in 1938 as a suburban railway tunnel project.", "https://www.swm.de/unternehmen/magazin/leben/mvg-50-jahre-ubahn", null, "2026-10-28"),
    JourneyContent("facts-163", JourneyContentKind.FACT, "Vor dem Fahrgaststart 1971 wurde Münchens neue U-Bahn bereits vier Jahre lang im Probebetrieb erprobt.", "Before passenger service began in 1971, Munich's new underground underwent four years of trial operation.", "https://www.swm.de/unternehmen/magazin/leben/mvg-50-jahre-ubahn", null, "2026-10-28"),
    JourneyContent("facts-164", JourneyContentKind.FACT, "Schienen, Schwellen, Schotter und Weichen bilden gemeinsam den Oberbau, auf dem Züge fahren.", "Rails, sleepers, ballast and switches together form the track structure on which trains run.", "https://www.networkrail.co.uk/our-work/looking-after-the-railway/track/", null, "2026-10-28"),
    JourneyContent("facts-165", JourneyContentKind.FACT, "Stopfmaschinen verdichten den Schotter unter den Schwellen, damit das Gleis seine genaue Lage behält.", "Tamping machines compact ballast beneath sleepers to maintain precise track geometry.", "https://www.networkrail.co.uk/our-work/looking-after-the-railway/track/", null, "2026-10-28"),
    JourneyContent("facts-166", JourneyContentKind.FACT, "Beim Schienenschleifen wird Material am Schienenkopf gezielt abgetragen, um die Lauffläche zu verbessern.", "Rail grinding deliberately removes material from the rail head to improve the running surface.", "https://www.networkrail.co.uk/our-work/looking-after-the-railway/track/", null, "2026-10-28"),
    JourneyContent("facts-167", JourneyContentKind.FACT, "Messgeräte an Zügen helfen Network Rail, Fehler im Gleis während der Fahrt zu erkennen.", "Equipment fitted to trains helps Network Rail detect track faults while moving.", "https://www.networkrail.co.uk/our-work/looking-after-the-railway/track/", null, "2026-10-28"),
    JourneyContent("facts-168", JourneyContentKind.FACT, "Weichen und Kreuzungen verschleißen besonders stark, weil Züge ihre beweglichen und kreuzenden Teile belasten.", "Switches and crossings suffer particular wear as trains load their moving and intersecting parts.", "https://www.networkrail.co.uk/our-work/looking-after-the-railway/track/", null, "2026-10-28"),
    JourneyContent("facts-169", JourneyContentKind.FACT, "Bei erkannten Störungen schaltet Network Rails Signalsystem auf Halt: Verzögerung kann eine Sicherheitsreaktion sein.", "When faults are detected, Network Rail's signalling stops trains: a delay can be a safety response.", "https://www.networkrail.co.uk/rail-travel/delays-explained/signals-and-points-failure/", null, "2026-10-28"),
    JourneyContent("facts-170", JourneyContentKind.FACT, "Elektrische Weichenheizungen verhindern, dass Eis die beweglichen Teile einer Weiche blockiert.", "Electric point heaters prevent ice from blocking a switch's moving parts.", "https://www.networkrail.co.uk/rail-travel/delays-explained/signals-and-points-failure/", null, "2026-10-28"),
    JourneyContent("facts-171", JourneyContentKind.FACT, "Network Rail überwacht viele Weichen aus der Ferne, um Fehler schon vor einem Ausfall zu entdecken.", "Network Rail remotely monitors many switches to detect faults before a failure.", "https://www.networkrail.co.uk/rail-travel/delays-explained/signals-and-points-failure/", null, "2026-10-28"),
    JourneyContent("facts-172", JourneyContentKind.FACT, "Weiß gestrichene Schienen können laut Network Rail fünf bis zehn Grad kühler bleiben als ungestrichene.", "According to Network Rail, white-painted rails can stay five to ten degrees cooler than unpainted rails.", "https://www.networkrail.co.uk/rail-travel/delays-explained/signals-and-points-failure/", null, "2026-10-28"),
    JourneyContent("facts-173", JourneyContentKind.FACT, "Eine defekte Weiche kann manchmal in einer sicheren Stellung festgelegt werden, damit Züge wieder passieren.", "A failed switch can sometimes be secured in one safe position so trains can pass again.", "https://www.networkrail.co.uk/rail-travel/delays-explained/signals-and-points-failure/", null, "2026-10-28"),
    JourneyContent("facts-174", JourneyContentKind.FACT, "Die britische Stromschiene wird über Unterwerke gespeist, die Hochspannungswechselstrom in 750 Volt Gleichstrom umwandeln.", "Britain's conductor rail is supplied by substations converting high-voltage AC into 750 volts DC.", "https://www.networkrail.co.uk/our-work/looking-after-the-railway/track/third-rail/", null, "2026-10-28"),
    JourneyContent("facts-175", JourneyContentKind.FACT, "Stromschienen sind in einzeln schaltbare elektrische Abschnitte aufgeteilt.", "Conductor rails are divided into electrical sections that can be switched individually.", "https://www.networkrail.co.uk/our-work/looking-after-the-railway/track/third-rail/", null, "2026-10-28"),
    JourneyContent("facts-176", JourneyContentKind.FACT, "Bei Network Rail werden Stromschienenabschnitte an beiden Enden gespeist, um die Versorgung zuverlässiger zu machen.", "Network Rail feeds conductor rail sections at both ends to improve supply reliability.", "https://www.networkrail.co.uk/our-work/looking-after-the-railway/track/third-rail/", null, "2026-10-28"),
    JourneyContent("facts-177", JourneyContentKind.FACT, "Ein „Track Paralleling Hut“ kann die Stromschienenversorgung effizienter machen, ohne selbst Strom einzuspeisen.", "A track paralleling hut can improve conductor rail efficiency without adding its own power supply.", "https://www.networkrail.co.uk/our-work/looking-after-the-railway/track/third-rail/", null, "2026-10-28"),
    JourneyContent("facts-178", JourneyContentKind.FACT, "Die Abstände britischer Stromschienen-Unterwerke hängen auch davon ab, wie dicht die Züge fahren.", "Spacing between British conductor rail substations also depends on how intensively trains use the line.", "https://www.networkrail.co.uk/our-work/looking-after-the-railway/track/third-rail/", null, "2026-10-28"),
    JourneyContent("facts-179", JourneyContentKind.FACT, "Der Tokaido-Shinkansen eröffnete am 1. Oktober 1964, nur neun Tage vor dem Beginn der Olympischen Spiele in Tokio.", "The Tokaido Shinkansen opened on 1 October 1964, just nine days before the Tokyo Olympics began.", "https://www.archives.go.jp/exhibition/digital/high-growth/contents/14/index02.html", null, "2026-10-28"),
    JourneyContent("facts-180", JourneyContentKind.FACT, "Beim Start 1964 dauerte die Shinkansen-Fahrt zwischen Tokio und Osaka vier Stunden.", "At its 1964 launch, the Shinkansen journey between Tokyo and Osaka took four hours.", "https://www.archives.go.jp/exhibition/digital/high-growth/contents/14/index02.html", null, "2026-10-28"),
    JourneyContent("facts-181", JourneyContentKind.FACT, "Die Bauarbeiten für den Tokaido-Shinkansen begannen im April 1959; für die Fertigstellung waren nur fünf Jahre vorgesehen.", "Construction of the Tokaido Shinkansen began in April 1959, with just five years planned for completion.", "https://www.archives.go.jp/exhibition/digital/high-growth/contents/14/index02.html", null, "2026-10-28"),
    JourneyContent("facts-182", JourneyContentKind.FACT, "Beim Bau des Tokaido-Shinkansen wurden teilweise schon vor dem Krieg erworbene Flächen und begonnene Arbeiten genutzt.", "Construction of the Tokaido Shinkansen partly reused land acquired and works begun before the war.", "https://www.archives.go.jp/exhibition/digital/high-growth/contents/14/index02.html", null, "2026-10-28"),
    JourneyContent("facts-183", JourneyContentKind.FACT, "Der Tokaido-Shinkansen nutzt eigene Gleise für Hochgeschwindigkeits-Personenzüge, getrennt vom gewöhnlichen Bahnverkehr.", "The Tokaido Shinkansen uses dedicated tracks for high-speed passenger trains, separate from ordinary rail traffic.", "https://global.jr-central.co.jp/en/company/ir/annualreport/_pdf/annualreport2024-11.pdf", null, "2026-10-28"),
    JourneyContent("facts-184", JourneyContentKind.FACT, "Auf den eigenen Strecken des Tokaido-Shinkansen gibt es keine Bahnübergänge.", "There are no level crossings on the Tokaido Shinkansen's dedicated tracks.", "https://global.jr-central.co.jp/en/company/ir/annualreport/_pdf/annualreport2024-11.pdf", null, "2026-10-28"),
    JourneyContent("facts-185", JourneyContentKind.FACT, "Die automatische Zugsteuerung des Shinkansen überwacht die zulässige Geschwindigkeit und hilft, Kollisionen zu vermeiden.", "The Shinkansen's automatic train control monitors permitted speed and helps prevent collisions.", "https://global.jr-central.co.jp/en/company/ir/annualreport/_pdf/annualreport2024-11.pdf", null, "2026-10-28"),
    JourneyContent("facts-186", JourneyContentKind.FACT, "JR Central setzt gegen Felsstürze sowohl Erkennungseinrichtungen als auch baulichen Schutz an gefährdeten Strecken ein.", "JR Central uses both rockfall detectors and physical protection on vulnerable routes.", "https://global.jr-central.co.jp/en/company/ir/annualreport/_pdf/annualreport2024-11.pdf", null, "2026-10-28"),
    JourneyContent("facts-187", JourneyContentKind.FACT, "Helsinkis erste Metrofahrgäste fuhren am 1. Juni 1982 zwischen Hakaniemi und Itäkeskus.", "Helsinki's first metro passengers travelled between Hakaniemi and Itäkeskus on 1 June 1982.", "https://historia.hel.fi/fi/ilmiot/liikenteen-solmukohta/metro", null, "2026-10-28"),
    JourneyContent("facts-188", JourneyContentKind.FACT, "Helsinkis erste Metrozüge wurden von Valmet im finnischen Tampere gebaut.", "Helsinki's first metro trains were built by Valmet in Tampere, Finland.", "https://historia.hel.fi/fi/ilmiot/liikenteen-solmukohta/metro", null, "2026-10-28"),
    JourneyContent("facts-189", JourneyContentKind.FACT, "Helsinkis Metro erreichte Mellunmäki 1989 und Vuosaari 1998.", "Helsinki's metro reached Mellunmäki in 1989 and Vuosaari in 1998.", "https://historia.hel.fi/fi/ilmiot/liikenteen-solmukohta/metro", null, "2026-10-28"),
    JourneyContent("facts-190", JourneyContentKind.FACT, "Die Verlängerung nach Ruoholahti von 1993 legte Helsinkis westliche Metroführung in Richtung Espoo fest.", "The 1993 extension to Ruoholahti established Helsinki's westward metro alignment towards Espoo.", "https://historia.hel.fi/fi/ilmiot/liikenteen-solmukohta/metro", null, "2026-10-28"),
    JourneyContent("facts-191", JourneyContentKind.FACT, "Helsinkis orange Metrozüge gehörten von Beginn des Fahrgastbetriebs 1982 zum Stadtbild.", "Helsinki's orange metro trains have been part of the city since passenger service began in 1982.", "https://historia.hel.fi/fi/ilmiot/liikenteen-solmukohta/metro", null, "2026-10-28"),
    JourneyContent("facts-192", JourneyContentKind.FACT, "Londons City and South London Railway eröffnete 1890 als erste elektrische Tiefen-U-Bahn der Welt.", "London's City and South London Railway opened in 1890 as the world's first deep-level electric railway.", "https://tfl-newsroom.prgloo.com/news/tfl-press-release-happy-birthday-london-underground-the-worlds-first-underground-railway-the-tube-celebrates-160-years-of-serving-the-capital", null, "2026-10-28"),
    JourneyContent("facts-193", JourneyContentKind.FACT, "Die Londoner Central Railway eröffnete 1900 zwischen Shepherd's Bush und Bank und wurde als „Twopenny Tube“ bekannt.", "London's Central Railway opened between Shepherd's Bush and Bank in 1900, becoming known as the Twopenny Tube.", "https://tfl-newsroom.prgloo.com/news/tfl-press-release-happy-birthday-london-underground-the-worlds-first-underground-railway-the-tube-celebrates-160-years-of-serving-the-capital", null, "2026-10-28"),
    JourneyContent("facts-194", JourneyContentKind.FACT, "Die heutigen Londoner Linien Bakerloo und Piccadilly nahmen beide 1906 den Betrieb auf.", "London's present-day Bakerloo and Piccadilly lines both began operating in 1906.", "https://tfl-newsroom.prgloo.com/news/tfl-press-release-happy-birthday-london-underground-the-worlds-first-underground-railway-the-tube-celebrates-160-years-of-serving-the-capital", null, "2026-10-28"),
    JourneyContent("facts-195", JourneyContentKind.FACT, "Der Name „Underground“ erschien 1908 erstmals in Londons U-Bahn-Stationen.", "The name Underground first appeared in London's subway stations in 1908.", "https://tfl-newsroom.prgloo.com/news/tfl-press-release-happy-birthday-london-underground-the-worlds-first-underground-railway-the-tube-celebrates-160-years-of-serving-the-capital", null, "2026-10-28"),
    JourneyContent("facts-196", JourneyContentKind.FACT, "1969 eröffnete Königin Elizabeth II. Londons Victoria Line offiziell.", "Queen Elizabeth II officially opened London’s Victoria Line in 1969.", "https://tfl-newsroom.prgloo.com/news/tfl-press-release-happy-birthday-london-underground-the-worlds-first-underground-railway-the-tube-celebrates-160-years-of-serving-the-capital", null, "2026-10-28"),
    JourneyContent("facts-197", JourneyContentKind.FACT, "Dresdens Schwebebahn hängt an einer Schiene, wird aber durch ein Zugseil statt durch Motoren in den Wagen bewegt.", "Dresden's suspension railway hangs from a rail but is moved by a haulage rope rather than onboard motors.", "https://www.dvb.de/de-de/entdecken/bergbahnen/schwebebahn", null, "2026-10-28"),
    JourneyContent("facts-198", JourneyContentKind.FACT, "Die Dresdner Schwebebahn verbindet Loschwitz und Oberloschwitz auf nur 273,8 Metern Strecke.", "Dresden's suspension railway connects Loschwitz and Oberloschwitz over just 273.8 metres.", "https://www.dvb.de/de-de/entdecken/bergbahnen/schwebebahn", null, "2026-10-28"),
    JourneyContent("facts-199", JourneyContentKind.FACT, "Auf ihrer kurzen Strecke überwindet Dresdens Schwebebahn 84,2 Meter Höhenunterschied.", "Over its short route, Dresden's suspension railway climbs 84.2 vertical metres.", "https://www.dvb.de/de-de/entdecken/bergbahnen/schwebebahn", null, "2026-10-28"),
    JourneyContent("facts-200", JourneyContentKind.FACT, "Die maximale Steigung der Dresdner Schwebebahn beträgt 39,9 Prozent.", "Dresden's suspension railway reaches a maximum gradient of 39.9 per cent.", "https://www.dvb.de/de-de/entdecken/bergbahnen/schwebebahn", null, "2026-10-28"),
    JourneyContent("facts-201", JourneyContentKind.FACT, "Dresdens zunächst dampfbetriebene Schwebebahn erhielt 1909 einen elektrischen Antrieb in der Bergstation.", "Dresden's initially steam-powered suspension railway gained an electric drive at its upper station in 1909.", "https://www.dvb.de/de-de/entdecken/bergbahnen/schwebebahn", null, "2026-10-28"),
    JourneyContent("facts-202", JourneyContentKind.FACT, "Stockholms U-Bahn wurde am 1. Oktober 1950 eröffnet.", "Stockholm's metro opened on 1 October 1950.", "https://stockholmskallan.stockholm.se/teman/stockholm-i-konsten/konsten-i-stockholms-tunnelbana/", null, "2026-10-28"),
    JourneyContent("facts-203", JourneyContentKind.FACT, "Stockholms U-Bahn-Kunst soll Stationen unverwechselbar machen und Fahrgästen die Orientierung erleichtern.", "Art in Stockholm's metro is intended to make stations distinctive and help passengers find their way.", "https://stockholmskallan.stockholm.se/teman/stockholm-i-konsten/konsten-i-stockholms-tunnelbana/", null, "2026-10-28"),
    JourneyContent("facts-204", JourneyContentKind.FACT, "In Stockholms U-Bahn begegnen Fahrgäste Skulpturen, Mosaiken, Malereien, Installationen und Reliefs.", "Stockholm metro passengers encounter sculptures, mosaics, paintings, installations and reliefs.", "https://stockholmskallan.stockholm.se/teman/stockholm-i-konsten/konsten-i-stockholms-tunnelbana/", null, "2026-10-28"),
    JourneyContent("facts-205", JourneyContentKind.FACT, "Auch ältere Stockholmer U-Bahn-Stationen, die ohne Kunst entstanden, erhielten später eigene Werke.", "Older Stockholm metro stations originally built without art received works later.", "https://stockholmskallan.stockholm.se/teman/stockholm-i-konsten/konsten-i-stockholms-tunnelbana/", null, "2026-10-28"),
    JourneyContent("facts-206", JourneyContentKind.FACT, "Die Künstlerin Siri Derkert gehörte zu den treibenden Kräften hinter Kunst in Stockholms U-Bahn.", "Artist Siri Derkert was one of the driving forces behind art in Stockholm's metro.", "https://stockholmskallan.stockholm.se/teman/stockholm-i-konsten/konsten-i-stockholms-tunnelbana/", null, "2026-10-28"),
    JourneyContent("facts-207", JourneyContentKind.FACT, "Madrids erste Metrolinie eröffnete am 17. Oktober 1919 mit acht Stationen zwischen Sol und Cuatro Caminos.", "Madrid's first metro line opened on 17 October 1919 with eight stations between Sol and Cuatro Caminos.", "https://www.casareal.es/ES/actividades/Paginas/actividades_actividades_detalle.aspx?data=13735", null, "2026-10-28"),
    JourneyContent("facts-208", JourneyContentKind.FACT, "Madrids erste Metrostrecke war vier Kilometer lang; die Züge brauchten dafür etwa zehn Minuten.", "Madrid's first metro route was four kilometres long, taking trains about ten minutes.", "https://www.casareal.es/ES/actividades/Paginas/actividades_actividades_detalle.aspx?data=13735", null, "2026-10-28"),
    JourneyContent("facts-209", JourneyContentKind.FACT, "Die Züge auf Madrids erster Metrostrecke fuhren 1919 mit einer Geschwindigkeit von etwa 25 km/h.", "Trains on Madrid's first metro route ran at about 25 km/h in 1919.", "https://www.casareal.es/ES/actividades/Paginas/actividades_actividades_detalle.aspx?data=13735", null, "2026-10-28"),
    JourneyContent("facts-210", JourneyContentKind.FACT, "Eine Fahrkarte für Madrids neue Metro kostete 1919 fünfzehn Céntimos.", "A ticket for Madrid's new metro cost fifteen céntimos in 1919.", "https://www.casareal.es/ES/actividades/Paginas/actividades_actividades_detalle.aspx?data=13735", null, "2026-10-28"),
    JourneyContent("facts-211", JourneyContentKind.FACT, "Für Madrids Metro-Jubiläum wurden zehn historische Wagen restauriert, darunter Fahrzeuge der ersten Betriebsgeneration.", "Ten historic cars were restored for Madrid's metro anniversary, including vehicles from its first operating generation.", "https://www.casareal.es/ES/actividades/Paginas/actividades_actividades_detalle.aspx?data=13735", null, "2026-10-28"),
    JourneyContent("facts-212", JourneyContentKind.FACT, "Merkur ist der kleinste Planet unseres Sonnensystems.", "Mercury is the smallest planet in our solar system.", "https://science.nasa.gov/mercury/facts/", null, "2026-10-30"),
    JourneyContent("facts-213", JourneyContentKind.FACT, "Ein Merkurjahr dauert nur etwa 88 Erdtage.", "A year on Mercury lasts about 88 Earth days.", "https://science.nasa.gov/mercury/facts/", null, "2026-10-30"),
    JourneyContent("facts-214", JourneyContentKind.FACT, "Zwischen zwei Sonnenaufgängen vergehen auf Merkur etwa 176 Erdtage.", "About 176 Earth days pass between sunrises on Mercury.", "https://science.nasa.gov/mercury/facts/", null, "2026-10-30"),
    JourneyContent("facts-215", JourneyContentKind.FACT, "Merkur besitzt keinen eigenen Mond.", "Mercury has no moon of its own.", "https://science.nasa.gov/mercury/facts/", null, "2026-10-30"),
    JourneyContent("facts-216", JourneyContentKind.FACT, "Viele Merkurkrater tragen Namen verstorbener Künstler, Musiker und Schriftsteller.", "Many Mercury craters honor deceased artists, musicians and writers.", "https://science.nasa.gov/mercury/facts/", null, "2026-10-30"),
    JourneyContent("facts-217", JourneyContentKind.FACT, "Merkur besitzt nur eine dünne Exosphäre statt einer dichten Atmosphäre.", "Mercury has a thin exosphere instead of a dense atmosphere.", "https://science.nasa.gov/mercury/facts/", null, "2026-10-30"),
    JourneyContent("facts-218", JourneyContentKind.FACT, "Auf Merkur reichen Temperaturen ungefähr von minus 180 bis 430 Grad.", "Mercury temperatures range roughly from minus 180 to 430 Celsius.", "https://science.nasa.gov/mercury/facts/", null, "2026-10-30"),
    JourneyContent("facts-219", JourneyContentKind.FACT, "Von Merkur aus wirkt die Sonne über dreimal so groß.", "From Mercury, the Sun appears over three times as large.", "https://science.nasa.gov/mercury/facts/", null, "2026-10-30"),
    JourneyContent("facts-220", JourneyContentKind.FACT, "Venus ist der heißeste Planet unseres Sonnensystems.", "Venus is the hottest planet in our solar system.", "https://science.nasa.gov/venus/venus-facts/", null, "2026-10-30"),
    JourneyContent("facts-221", JourneyContentKind.FACT, "Eine Venusrotation dauert länger als ein Venusjahr: etwa 243 statt 225 Erdtage.", "One Venus rotation outlasts its year: about 243 versus 225 Earth days.", "https://science.nasa.gov/venus/venus-facts/", null, "2026-10-30"),
    JourneyContent("facts-222", JourneyContentKind.FACT, "Auf Venus geht die Sonne im Westen auf.", "On Venus, the Sun rises in the west.", "https://science.nasa.gov/venus/venus-facts/", null, "2026-10-30"),
    JourneyContent("facts-223", JourneyContentKind.FACT, "Venus trägt ungefähr den 93-fachen Luftdruck unseres Meeresspiegels.", "Venus has roughly 93 times our sea-level atmospheric pressure.", "https://science.nasa.gov/venus/venus-facts/", null, "2026-10-30"),
    JourneyContent("facts-224", JourneyContentKind.FACT, "Die dichten Wolken der Venus enthalten Schwefelsäure.", "Venus’s thick clouds contain sulfuric acid.", "https://science.nasa.gov/venus/venus-facts/", null, "2026-10-30"),
    JourneyContent("facts-225", JourneyContentKind.FACT, "Venus hat keinen natürlichen Mond.", "Venus has no natural moon.", "https://science.nasa.gov/venus/venus-facts/", null, "2026-10-30"),
    JourneyContent("facts-226", JourneyContentKind.FACT, "Venus ist fast so groß wie die Erde.", "Venus is almost as large as Earth.", "https://science.nasa.gov/venus/venus-facts/", null, "2026-10-30"),
    JourneyContent("facts-227", JourneyContentKind.FACT, "Nach dem Mond ist Venus das hellste natürliche Nachthimmelsobjekt.", "After the Moon, Venus is the brightest natural night-sky object.", "https://science.nasa.gov/venus/venus-facts/", null, "2026-10-30"),
    JourneyContent("facts-228", JourneyContentKind.FACT, "Ein Tag auf Mars dauert etwa 24,6 Stunden.", "A day on Mars lasts about 24.6 hours.", "https://science.nasa.gov/mars/facts/", null, "2026-10-30"),
