    JourneyContent("facts-319", JourneyContentKind.FACT, "Auch Gürteltiere tragen Haare: unter anderem am Bauch und an den Körperseiten.", "Armadillos have hair too, including on their bellies and sides.", "https://animals.sandiegozoo.org/animals/armadillo", null, "2026-10-31"),
    JourneyContent("facts-320", JourneyContentKind.FACT, "Zwischen den harten Panzerbändern eines Gürteltiers liegt dehnbare Haut. Der Panzer ist beweglich.", "Stretchy skin between an armadillo's hard armour bands lets the shell flex.", "https://animals.sandiegozoo.org/animals/armadillo", null, "2026-10-31"),
    JourneyContent("facts-321", JourneyContentKind.FACT, "„Armadillo“, der englische Gürteltiername, kommt aus dem Spanischen und bedeutet sinngemäß „kleines gepanzertes Tier“.", "The word armadillo comes from Spanish and roughly means little armoured animal.", "https://animals.sandiegozoo.org/animals/armadillo", null, "2026-10-31"),
    JourneyContent("facts-322", JourneyContentKind.FACT, "Fledermäuse sind die einzigen Säugetiere, die aus eigener Kraft dauerhaft fliegen können.", "Bats are the only mammals capable of sustained powered flight.", "https://animals.sandiegozoo.org/animals/bat", null, "2026-10-31"),
    JourneyContent("facts-323", JourneyContentKind.FACT, "Ein Fledermausflügel ist eine umgestaltete Hand mit stark verlängerten Fingern.", "A bat wing is a modified hand with greatly elongated fingers.", "https://animals.sandiegozoo.org/animals/bat", null, "2026-10-31"),
    JourneyContent("facts-324", JourneyContentKind.FACT, "Winzige Sinneshaare auf Fledermausflügeln helfen, den Luftstrom beim Fliegen wahrzunehmen.", "Tiny sensory hairs on bat wings help detect airflow during flight.", "https://animals.sandiegozoo.org/animals/bat", null, "2026-10-31"),
    JourneyContent("facts-325", JourneyContentKind.FACT, "Fledermäuse sind nicht blind. Manche Arten besitzen sogar ein ausgezeichnetes Sehvermögen.", "Bats are not blind; some species have excellent eyesight.", "https://animals.sandiegozoo.org/animals/bat", null, "2026-10-31"),
    JourneyContent("facts-326", JourneyContentKind.FACT, "Von den vielen Fledermausarten ernähren sich nur drei von Blut.", "Only three bat species feed on blood.", "https://animals.sandiegozoo.org/animals/bat", null, "2026-10-31"),
    JourneyContent("facts-327", JourneyContentKind.FACT, "Vampirfledermäuse können verwaiste Jungtiere adoptieren.", "Vampire bats can adopt orphaned young.", "https://animals.sandiegozoo.org/animals/bat", null, "2026-10-31"),
    JourneyContent("facts-328", JourneyContentKind.FACT, "Rote Pandas haben einen „falschen Daumen“ aus einem umgebildeten Handwurzelknochen zum Bambusgreifen.", "Red pandas grip bamboo using a false thumb formed from a wrist bone.", "https://animals.sandiegozoo.org/animals/red-panda", null, "2026-10-31"),
    JourneyContent("facts-329", JourneyContentKind.FACT, "Rote Pandas gehören zu einer eigenen Säugetierfamilie, den Ailuridae.", "Red pandas belong to their own mammal family, Ailuridae.", "https://animals.sandiegozoo.org/animals/red-panda", null, "2026-10-31"),
    JourneyContent("facts-330", JourneyContentKind.FACT, "Fast die Hälfte der Gesamtlänge eines Roten Pandas kann auf seinen Schwanz entfallen.", "A red panda's tail can account for almost half its total length.", "https://animals.sandiegozoo.org/animals/red-panda", null, "2026-10-31"),
    JourneyContent("facts-331", JourneyContentKind.FACT, "Rote Pandas können kopfüber einen Baumstamm hinunterklettern.", "Red pandas can climb down tree trunks head first.", "https://animals.sandiegozoo.org/animals/red-panda", null, "2026-10-31"),
    JourneyContent("facts-332", JourneyContentKind.FACT, "Rote Pandas gehören zur Ordnung der Raubtiere, obwohl sie überwiegend Bambus fressen.", "Red pandas belong to the carnivore order despite eating mostly bamboo.", "https://animals.sandiegozoo.org/animals/red-panda", null, "2026-10-31"),
    JourneyContent("facts-333", JourneyContentKind.FACT, "Fossilien zeigen: Vor Millionen Jahren lebten Verwandte heutiger Roter Pandas auch in Nordamerika.", "Fossils show relatives of modern red pandas lived in North America millions of years ago.", "https://animals.sandiegozoo.org/animals/red-panda", null, "2026-10-31"),
    JourneyContent("facts-334", JourneyContentKind.FACT, "Flamingos werden durch Farbstoffe aus ihrer Nahrung rosa, nicht durch eine angeborene rosa Federfarbe.", "Flamingos turn pink from dietary pigments, rather than an inborn pink feather colour.", "https://animals.sandiegozoo.org/animals/flamingo", null, "2026-10-31"),
    JourneyContent("facts-335", JourneyContentKind.FACT, "Beim Fressen halten Flamingos den Schnabel verkehrt herum ins Wasser und filtern ihre Nahrung heraus.", "Flamingos feed with their bills upside down in water, filtering out food.", "https://animals.sandiegozoo.org/animals/flamingo", null, "2026-10-31"),
    JourneyContent("facts-336", JourneyContentKind.FACT, "Flamingoeltern füttern Küken mit einer nährstoffreichen Flüssigkeit aus ihrem oberen Verdauungstrakt.", "Flamingo parents feed chicks nutrient-rich fluid from their upper digestive tract.", "https://animals.sandiegozoo.org/animals/flamingo", null, "2026-10-31"),
    JourneyContent("facts-337", JourneyContentKind.FACT, "Flamingos bauen ihre Nester als kleine Hügel aus Schlamm.", "Flamingos build nests as little mounds of mud.", "https://animals.sandiegozoo.org/animals/flamingo", null, "2026-10-31"),
    JourneyContent("facts-338", JourneyContentKind.FACT, "Flamingos brauchen beim Abheben meist einige Anlaufschritte und starten bevorzugt gegen den Wind.", "Flamingos usually need running steps to take off, preferably into the wind.", "https://animals.sandiegozoo.org/animals/flamingo", null, "2026-10-31"),
    JourneyContent("facts-339", JourneyContentKind.FACT, "Eine ausgefallene Flamingofeder verliert ihre rosa Farbe relativ schnell.", "A shed flamingo feather loses its pink colour relatively quickly.", "https://animals.sandiegozoo.org/animals/flamingo", null, "2026-10-31"),
    JourneyContent("facts-340", JourneyContentKind.FACT, "Giraffen haben gewöhnlich sieben Halswirbel – genauso viele wie Menschen.", "Giraffes normally have seven neck vertebrae, just like humans.", "https://animals.sandiegozoo.org/animals/giraffe", null, "2026-10-31"),
    JourneyContent("facts-341", JourneyContentKind.FACT, "Eine Giraffenzunge kann ungefähr einen halben Meter lang werden.", "A giraffe's tongue can grow to roughly half a metre long.", "https://animals.sandiegozoo.org/animals/giraffe", null, "2026-10-31"),
    JourneyContent("facts-342", JourneyContentKind.FACT, "Giraffenfüße erreichen ungefähr die Breite eines großen Esstellers: rund 30 Zentimeter.", "Giraffe feet can be dinner-plate wide: roughly 30 centimetres across.", "https://animals.sandiegozoo.org/animals/giraffe", null, "2026-10-31"),
    JourneyContent("facts-343", JourneyContentKind.FACT, "Giraffenaugen sind etwa so groß wie Golfbälle.", "Giraffe eyes are approximately golf-ball sized.", "https://animals.sandiegozoo.org/animals/giraffe", null, "2026-10-31"),
    JourneyContent("facts-344", JourneyContentKind.FACT, "Giraffenkälber können in ihrer ersten Woche täglich ungefähr 2,5 Zentimeter wachsen.", "Giraffe calves can grow roughly 2.5 centimetres daily during their first week.", "https://animals.sandiegozoo.org/animals/giraffe", null, "2026-10-31"),
    JourneyContent("facts-345", JourneyContentKind.FACT, "Giraffen erreichen beim Rennen Geschwindigkeiten von ungefähr 56 Kilometern pro Stunde.", "Giraffes can run at approximately 56 kilometres per hour.", "https://animals.sandiegozoo.org/animals/giraffe", null, "2026-10-31"),
    JourneyContent("facts-346", JourneyContentKind.FACT, "Eulen bewegen zur Blickänderung den Kopf, weil ihre Augen kaum beweglich sind.", "Owls turn their heads to look around because their eyes barely move.", "https://animals.sandiegozoo.org/animals/owl", null, "2026-10-31"),
    JourneyContent("facts-347", JourneyContentKind.FACT, "Viele Eulen können ihren Kopf bis zu etwa 270 Grad drehen, aber nicht endlos herumwirbeln.", "Many owls can turn their heads about 270 degrees, but cannot spin them indefinitely.", "https://animals.sandiegozoo.org/animals/owl", null, "2026-10-31"),
    JourneyContent("facts-348", JourneyContentKind.FACT, "Der Gesichtsschleier einer Eule hilft, Schall zu ihren Ohröffnungen zu lenken.", "An owl's facial disc helps funnel sound towards its ear openings.", "https://animals.sandiegozoo.org/animals/owl", null, "2026-10-31"),
    JourneyContent("facts-349", JourneyContentKind.FACT, "Weiche Federkanten machen den Flug vieler Eulen besonders leise.", "Soft feather edges make the flight of many owls especially quiet.", "https://animals.sandiegozoo.org/animals/owl", null, "2026-10-31"),
    JourneyContent("facts-350", JourneyContentKind.FACT, "Die auffälligen „Ohren“ mancher Eulen sind Federbüschel, nicht ihre eigentlichen Ohren.", "The conspicuous ears on some owls are feather tufts, not their actual ears.", "https://animals.sandiegozoo.org/animals/owl", null, "2026-10-31"),
    JourneyContent("facts-351", JourneyContentKind.FACT, "Schleiereulen haben einen herzförmigen Gesichtsschleier; viele andere Eulen einen runden.", "Barn owls have heart-shaped facial discs; many other owls have round ones.", "https://animals.sandiegozoo.org/animals/owl", null, "2026-10-31"),
    JourneyContent("facts-352", JourneyContentKind.FACT, "Brillenpinguine leben an südafrikanischen Küsten. Für Pinguine braucht es keinen antarktischen Schnee.", "African penguins inhabit southern African coasts; penguins do not require Antarctic snow.", "https://animals.sandiegozoo.org/animals/african-penguin", null, "2026-10-31"),
    JourneyContent("facts-353", JourneyContentKind.FACT, "Das Fleckenmuster auf der Brust eines Brillenpinguins ist individuell erkennbar.", "An African penguin's chest spot pattern is individually distinctive.", "https://animals.sandiegozoo.org/animals/african-penguin", null, "2026-10-31"),
    JourneyContent("facts-354", JourneyContentKind.FACT, "Nackte Haut über den Augen hilft Brillenpinguinen, überschüssige Körperwärme abzugeben.", "Bare skin above the eyes helps African penguins release excess body heat.", "https://animals.sandiegozoo.org/animals/african-penguin", null, "2026-10-31"),
    JourneyContent("facts-355", JourneyContentKind.FACT, "Bei Brillenpinguinen teilen sich beide Eltern das Ausbrüten der Eier.", "Both African penguin parents share egg incubation.", "https://animals.sandiegozoo.org/animals/african-penguin", null, "2026-10-31"),
    JourneyContent("facts-356", JourneyContentKind.FACT, "Brillenpinguine können länger als zwei Minuten die Luft anhalten.", "African penguins can hold their breath for over two minutes.", "https://animals.sandiegozoo.org/animals/african-penguin", null, "2026-10-31"),
    JourneyContent("facts-357", JourneyContentKind.FACT, "Brillenpinguin-Küken bilden Gruppen, während ihre Eltern Nahrung im Meer suchen.", "African penguin chicks gather in groups while their parents forage at sea.", "https://animals.sandiegozoo.org/animals/african-penguin", null, "2026-10-31"),
    JourneyContent("facts-358", JourneyContentKind.FACT, "Chamäleons können ihre Augen unabhängig voneinander bewegen und so zwei Richtungen gleichzeitig beobachten.", "Chameleons can move their eyes independently, watching two directions at once.", "https://animals.sandiegozoo.org/animals/chameleon", null, "2026-10-31"),
    JourneyContent("facts-359", JourneyContentKind.FACT, "Einige Chamäleons können ihre Zunge weiter herausschießen, als ihr Körper lang ist.", "Some chameleons can shoot their tongues farther than their body length.", "https://animals.sandiegozoo.org/animals/chameleon", null, "2026-10-31"),
    JourneyContent("facts-360", JourneyContentKind.FACT, "Farbwechsel von Chamäleons dienen auch der Kommunikation, nicht nur der Tarnung.", "Chameleon colour changes also communicate, rather than serving camouflage alone.", "https://animals.sandiegozoo.org/animals/chameleon", null, "2026-10-31"),
    JourneyContent("facts-361", JourneyContentKind.FACT, "Viele Chamäleons nutzen ihren Greifschwanz als zusätzliche Sicherung beim Klettern.", "Many chameleons use prehensile tails as extra security while climbing.", "https://animals.sandiegozoo.org/animals/chameleon", null, "2026-10-31"),
    JourneyContent("facts-362", JourneyContentKind.FACT, "Chamäleons häuten sich meist stückweise, nicht in einer einzigen langen Haut wie viele Schlangen.", "Chameleons usually shed skin in pieces, unlike the single long skin shed by many snakes.", "https://animals.sandiegozoo.org/animals/chameleon", null, "2026-10-31"),
    JourneyContent("facts-363", JourneyContentKind.FACT, "Der Name Chamäleon geht auf griechische Wörter für „Erde“ und „Löwe“ zurück.", "The name chameleon derives from Greek words for earth and lion.", "https://animals.sandiegozoo.org/animals/chameleon", null, "2026-10-31"),
    JourneyContent("facts-364", JourneyContentKind.FACT, "Krokodile sind stammesgeschichtlich näher mit Vögeln verwandt als mit den meisten anderen heutigen Reptilien.", "Crocodilians are evolutionarily closer to birds than to most other living reptiles.", "https://animals.sandiegozoo.org/animals/crocodilian", null, "2026-10-31"),
    JourneyContent("facts-365", JourneyContentKind.FACT, "Krokodile können ihre Jungen bereits hören, wenn diese noch im Ei sitzen.", "Crocodilians can hear their young while they are still inside eggs.", "https://animals.sandiegozoo.org/animals/crocodilian", null, "2026-10-31"),
    JourneyContent("facts-366", JourneyContentKind.FACT, "Krokodilzähne wachsen wiederholt nach. Ein Tier kann im Leben Tausende davon verbrauchen.", "Crocodilian teeth are repeatedly replaced; one animal can use thousands in its lifetime.", "https://animals.sandiegozoo.org/animals/crocodilian", null, "2026-10-31"),
    JourneyContent("facts-367", JourneyContentKind.FACT, "Die Zunge eines Krokodils ist am Mundboden befestigt und lässt sich kaum herausstrecken.", "A crocodilian's tongue is attached to its mouth floor and barely protrudes.", "https://animals.sandiegozoo.org/animals/crocodilian", null, "2026-10-31"),
    JourneyContent("facts-368", JourneyContentKind.FACT, "Krokodile können überschüssiges Salz über spezielle Zungendrüsen ausscheiden; Alligatoren besitzen diese so nicht.", "Crocodiles excrete excess salt through specialised tongue glands; alligators lack that system.", "https://animals.sandiegozoo.org/animals/crocodilian", null, "2026-10-31"),
    JourneyContent("facts-369", JourneyContentKind.FACT, "Sensoren in der Haut helfen Krokodilen, Bewegungen im trüben Wasser wahrzunehmen.", "Skin sensors help crocodilians detect movement in murky water.", "https://animals.sandiegozoo.org/animals/crocodilian", null, "2026-10-31"),
    JourneyContent("facts-370", JourneyContentKind.FACT, "Libellen können ihre beiden Flügelpaare unabhängig steuern und dadurch sogar rückwärts fliegen.", "Dragonflies can control their two wing pairs independently and even fly backwards.", "https://animals.sandiegozoo.org/animals/dragonfly-and-damselfly", null, "2026-10-31"),
    JourneyContent("facts-371", JourneyContentKind.FACT, "Libellen können wie kleine Hubschrauber auf der Stelle in der Luft stehen.", "Dragonflies can hover like tiny helicopters.", "https://animals.sandiegozoo.org/animals/dragonfly-and-damselfly", null, "2026-10-31"),
    JourneyContent("facts-372", JourneyContentKind.FACT, "Libellen-Facettenaugen können aus bis zu etwa 30.000 Einzellinsen bestehen.", "Dragonfly compound eyes can contain up to roughly 30,000 lenses.", "https://animals.sandiegozoo.org/animals/dragonfly-and-damselfly", null, "2026-10-31"),
    JourneyContent("facts-373", JourneyContentKind.FACT, "Libellenlarven leben im Wasser; erst die erwachsenen Tiere jagen durch die Luft.", "Dragonfly larvae live underwater; adults hunt through the air.", "https://animals.sandiegozoo.org/animals/dragonfly-and-damselfly", null, "2026-10-31"),
    JourneyContent("facts-374", JourneyContentKind.FACT, "Fossile libellenartige Insekten erreichten Flügelspannweiten um 70 Zentimeter.", "Fossil dragonfly-like insects reached wingspans around 70 centimetres.", "https://animals.sandiegozoo.org/animals/dragonfly-and-damselfly", null, "2026-10-31"),
    JourneyContent("facts-375", JourneyContentKind.FACT, "Großlibellen ruhen meist mit ausgebreiteten Flügeln, Kleinlibellen meist mit zusammengelegten.", "Dragonflies usually rest with spread wings; damselflies usually hold theirs together.", "https://animals.sandiegozoo.org/animals/dragonfly-and-damselfly", null, "2026-10-31"),
    JourneyContent("facts-376", JourneyContentKind.FACT, "Skorpione sind Spinnentiere mit acht Beinen, keine Insekten.", "Scorpions are eight-legged arachnids, not insects.", "https://animals.sandiegozoo.org/animals/scorpion", null, "2026-10-31"),
    JourneyContent("facts-377", JourneyContentKind.FACT, "Unter ultraviolettem Licht können Skorpione wegen Stoffen in ihrem Panzer leuchten.", "Scorpions can glow under ultraviolet light because of substances in their outer covering.", "https://animals.sandiegozoo.org/animals/scorpion", null, "2026-10-31"),
    JourneyContent("facts-378", JourneyContentKind.FACT, "Skorpionmütter tragen ihren Nachwuchs zum Schutz auf dem Rücken.", "Mother scorpions carry their young on their backs for protection.", "https://animals.sandiegozoo.org/animals/scorpion", null, "2026-10-31"),
    JourneyContent("facts-379", JourneyContentKind.FACT, "Kammartige Sinnesorgane an der Bauchunterseite helfen Skorpionen, ihre Umgebung zu ertasten.", "Comb-like organs beneath the abdomen help scorpions sense their surroundings.", "https://animals.sandiegozoo.org/animals/scorpion", null, "2026-10-31"),
    JourneyContent("facts-380", JourneyContentKind.FACT, "Skorpione atmen über sogenannte Buchlungen, deren Aufbau an gestapelte Seiten erinnert.", "Scorpions breathe through book lungs, arranged somewhat like stacked pages.", "https://animals.sandiegozoo.org/animals/scorpion", null, "2026-10-31"),
    JourneyContent("facts-381", JourneyContentKind.FACT, "Manche Skorpione heben bei Hitze ihren Körper vom Boden ab, um sich abzukühlen.", "Some scorpions raise their bodies off hot ground to cool down.", "https://animals.sandiegozoo.org/animals/scorpion", null, "2026-10-31"),
    JourneyContent("facts-382", JourneyContentKind.FACT, "Blattschneiderameisen fressen nicht einfach ihre Blattstücke: Sie züchten darauf Pilze als Nahrung.", "Leafcutter ants use leaf pieces to grow fungi for food rather than simply eating them.", "https://animals.sandiegozoo.org/animals/ant", null, "2026-10-31"),
    JourneyContent("facts-383", JourneyContentKind.FACT, "Manche Ameisen halten Blattläuse und „melken“ deren zuckerhaltigen Honigtau.", "Some ants tend aphids and milk their sugary honeydew.", "https://animals.sandiegozoo.org/animals/ant", null, "2026-10-31"),
    JourneyContent("facts-384", JourneyContentKind.FACT, "Honigtopfameisen speichern Vorräte in stark angeschwollenen Arbeiterinnen, die im Nest hängen.", "Honeypot ants store supplies in swollen workers hanging inside their nests.", "https://animals.sandiegozoo.org/animals/ant", null, "2026-10-31"),
    JourneyContent("facts-385", JourneyContentKind.FACT, "Ameisen legen Duftspuren, damit andere Mitglieder des Staates eine Nahrungsquelle finden.", "Ants lay scent trails so other colony members can locate food.", "https://animals.sandiegozoo.org/animals/ant", null, "2026-10-31"),
    JourneyContent("facts-386", JourneyContentKind.FACT, "Ameisen nutzen ihre Fühler nicht nur zum Tasten, sondern auch zum Riechen und Kommunizieren.", "Ants use antennae for touch, smell and communication.", "https://animals.sandiegozoo.org/animals/ant", null, "2026-10-31"),
    JourneyContent("facts-387", JourneyContentKind.FACT, "Einige Ameisen besitzen vergrößerte Soldatenarbeiterinnen mit besonders kräftigen Kiefern.", "Some ants have enlarged soldier workers with especially powerful jaws.", "https://animals.sandiegozoo.org/animals/ant", null, "2026-10-31"),
    JourneyContent("facts-388", JourneyContentKind.FACT, "Nacktmulle leben in Kolonien mit einer Königin und spezialisierten Arbeitern – ähnlich einem Insektenstaat.", "Naked mole-rats live in colonies with a queen and specialised workers, rather like social insects.", "https://animals.sandiegozoo.org/animals/naked-mole-rat", null, "2026-10-31"),
    JourneyContent("facts-389", JourneyContentKind.FACT, "Nacktmulle können ihre vorderen Zähne unabhängig voneinander bewegen, ähnlich kleinen Essstäbchen.", "Naked mole-rats can move their front teeth independently, rather like tiny chopsticks.", "https://animals.sandiegozoo.org/animals/naked-mole-rat", null, "2026-10-31"),
    JourneyContent("facts-390", JourneyContentKind.FACT, "Nacktmull-Bauten besitzen getrennte Räume für Nachwuchs, Vorräte und sogar eine Toilette.", "Naked mole-rat burrows have separate nursery, food-storage and even toilet chambers.", "https://animals.sandiegozoo.org/animals/naked-mole-rat", null, "2026-10-31"),
    JourneyContent("facts-391", JourneyContentKind.FACT, "Ganz nackt sind Nacktmulle nicht: Feine Sinneshaare helfen ihnen bei der Orientierung.", "Naked mole-rats are not entirely naked: fine sensory hairs help them navigate.", "https://animals.sandiegozoo.org/animals/naked-mole-rat", null, "2026-10-31"),
    JourneyContent("facts-392", JourneyContentKind.FACT, "Nacktmulle können durch ihre Tunnel sowohl vorwärts als auch rückwärts laufen.", "Naked mole-rats can run both forwards and backwards through their tunnels.", "https://animals.sandiegozoo.org/animals/naked-mole-rat", null, "2026-10-31"),
    JourneyContent("facts-393", JourneyContentKind.FACT, "Nacktmulle fressen einen Teil ihres Kots erneut, um zusätzliche Nährstoffe zu gewinnen.", "Naked mole-rats re-eat some droppings to extract additional nutrients.", "https://animals.sandiegozoo.org/animals/naked-mole-rat", null, "2026-10-31"),
    JourneyContent("facts-394", JourneyContentKind.FACT, "Baobab-Stämme können zu bis zu etwa 80 Prozent aus Wasser bestehen.", "Baobab trunks can contain up to roughly 80 percent water.", "https://www.kew.org/read-and-watch/extreme-plant-survivors-baobab", null, "2026-10-31"),
    JourneyContent("facts-395", JourneyContentKind.FACT, "Manche Baobabs werden auf mindestens tausend Jahre Alter geschätzt.", "Some baobabs are estimated to be at least a thousand years old.", "https://www.kew.org/read-and-watch/extreme-plant-survivors-baobab", null, "2026-10-31"),
    JourneyContent("facts-396", JourneyContentKind.FACT, "Aus der weichen, faserigen Baobab-Rinde lassen sich Seile und Stoffe herstellen.", "Soft, fibrous baobab bark can be used to make ropes and cloth.", "https://www.kew.org/read-and-watch/extreme-plant-survivors-baobab", null, "2026-10-31"),
    JourneyContent("facts-397", JourneyContentKind.FACT, "Baobab-Früchte enthalten bemerkenswerte Mengen Vitamin C und Calcium.", "Baobab fruits contain notable amounts of vitamin C and calcium.", "https://www.kew.org/read-and-watch/extreme-plant-survivors-baobab", null, "2026-10-31"),
    JourneyContent("facts-398", JourneyContentKind.FACT, "Kews Baobab musste regelmäßig beschnitten werden, damit er nicht durch das Gewächshausdach wächst.", "Kew's baobab needed regular pruning to prevent it growing through the conservatory roof.", "https://www.kew.org/read-and-watch/extreme-plant-survivors-baobab", null, "2026-10-31"),
    JourneyContent("facts-399", JourneyContentKind.FACT, "Küstenmammutbäume können aus einem Samen von ungefähr Tomatensamengröße über hundert Meter hoch wachsen.", "Coast redwoods can grow over a hundred metres tall from a tomato-seed-sized seed.", "https://www.nps.gov/redw/learn/nature/about-the-trees.htm", null, "2026-10-31"),
    JourneyContent("facts-400", JourneyContentKind.FACT, "Küstenmammutbäume können etwa zweitausend Jahre alt werden.", "Coast redwoods can live for roughly two thousand years.", "https://www.nps.gov/redw/learn/nature/about-the-trees.htm", null, "2026-10-31"),
    JourneyContent("facts-401", JourneyContentKind.FACT, "Mammutbaumverwandte wuchsen bereits im Jura, lange bevor Menschen existierten.", "Redwood relatives already grew in the Jurassic, long before humans existed.", "https://www.nps.gov/redw/learn/nature/about-the-trees.htm", null, "2026-10-31"),
    JourneyContent("facts-402", JourneyContentKind.FACT, "Küstenmammutbäume können aus Baumstümpfen oder Wurzeln neue, genetisch identische Stämme austreiben.", "Coast redwoods can sprout genetically identical new trunks from stumps or roots.", "https://www.nps.gov/redw/learn/nature/about-the-trees.htm", null, "2026-10-31"),
    JourneyContent("facts-403", JourneyContentKind.FACT, "Trotz ihrer enormen Höhe reichen die Wurzeln von Küstenmammutbäumen meist nur wenige Meter tief.", "Despite their enormous height, coast redwood roots usually extend only a few metres deep.", "https://www.nps.gov/redw/learn/nature/about-the-trees.htm", null, "2026-10-31"),
    JourneyContent("facts-404", JourneyContentKind.FACT, "Küstennebel versorgt Mammutbaumwälder auch während trockener Sommer mit Feuchtigkeit.", "Coastal fog supplies redwood forests with moisture even during dry summers.", "https://www.nps.gov/redw/learn/nature/about-the-trees.htm", null, "2026-10-31"),
    JourneyContent("facts-405", JourneyContentKind.FACT, "Eine Venusfliegenfalle reagiert meist erst auf zwei Berührungen ihrer Fühlhaare innerhalb von etwa zwanzig Sekunden.", "Venus flytraps usually require two trigger-hair touches within about twenty seconds.", "https://www.kew.org/read-and-watch/venus-flytrap-creepy-carnivorous-plant", null, "2026-10-31"),
    JourneyContent("facts-406", JourneyContentKind.FACT, "Venusfliegenfallen fangen ihre Beute mit umgebildeten Blättern, nicht mit einer Blüte.", "Venus flytraps catch prey with modified leaves, not a flower.", "https://www.kew.org/read-and-watch/venus-flytrap-creepy-carnivorous-plant", null, "2026-10-31"),
    JourneyContent("facts-407", JourneyContentKind.FACT, "Venusfliegenfallen stammen aus Feuchtgebieten in Nord- und Süd-Carolina, nicht aus tropischen Dschungeln.", "Venus flytraps originate in North and South Carolina wetlands, not tropical jungles.", "https://www.kew.org/read-and-watch/venus-flytrap-creepy-carnivorous-plant", null, "2026-10-31"),
    JourneyContent("facts-408", JourneyContentKind.FACT, "Nach dem Zuschnappen setzen Venusfliegenfallen Verdauungsenzyme frei, um ihre Beute zu zerlegen.", "After closing, Venus flytraps release digestive enzymes to break down prey.", "https://www.kew.org/read-and-watch/venus-flytrap-creepy-carnivorous-plant", null, "2026-10-31"),
    JourneyContent("facts-409", JourneyContentKind.FACT, "Eine Venusfliegenfalle kann ungefähr zehn Tage für die Verdauung brauchen, bevor sie wieder aufgeht.", "A Venus flytrap can take about ten days to digest prey before reopening.", "https://www.kew.org/read-and-watch/venus-flytrap-creepy-carnivorous-plant", null, "2026-10-31"),
    JourneyContent("facts-410", JourneyContentKind.FACT, "Venusfliegenfallen sind an nährstoffarme Böden angepasst; ihre tierische Beute ergänzt die Nährstoffversorgung.", "Venus flytraps are adapted to nutrient-poor soils; animal prey supplements their nutrient supply.", "https://www.kew.org/read-and-watch/venus-flytrap-creepy-carnivorous-plant", null, "2026-10-31"),
    JourneyContent("facts-411", JourneyContentKind.FACT, "Die riesige Titanwurz-Blüte ist tatsächlich ein Blütenstand aus vielen kleinen Einzelblüten.", "The giant titan arum bloom is actually a structure containing many tiny flowers.", "https://www.kew.org/read-and-watch/the-giant-pongy-plant-titan-arum", null, "2026-10-31"),
    JourneyContent("facts-412", JourneyContentKind.FACT, "Die Titanwurz kann selbst Wärme produzieren, wodurch sich ihr Aasgeruch besser verbreitet.", "Titan arum can generate heat, helping disperse its carrion-like smell.", "https://www.kew.org/read-and-watch/the-giant-pongy-plant-titan-arum", null, "2026-10-31"),
    JourneyContent("facts-413", JourneyContentKind.FACT, "Bei der Titanwurz öffnen sich weibliche Blüten vor den männlichen. Das erschwert Selbstbestäubung.", "Titan arum female flowers open before male ones, discouraging self-pollination.", "https://www.kew.org/read-and-watch/the-giant-pongy-plant-titan-arum", null, "2026-10-31"),
    JourneyContent("facts-414", JourneyContentKind.FACT, "Die Titanwurz wächst wild nur auf Sumatra.", "Titan arum grows wild only on Sumatra.", "https://www.kew.org/read-and-watch/the-giant-pongy-plant-titan-arum", null, "2026-10-31"),
    JourneyContent("facts-415", JourneyContentKind.FACT, "Zwischen Blühphasen bildet die Titanwurz ein einziges großes, baumähnliches Blatt.", "Between flowering periods, titan arum produces one huge, tree-like leaf.", "https://www.kew.org/read-and-watch/the-giant-pongy-plant-titan-arum", null, "2026-10-31"),
    JourneyContent("facts-416", JourneyContentKind.FACT, "Die Titanwurz speichert Energie für ihren riesigen Blütenstand in einer unterirdischen Knolle.", "Titan arum stores energy for its giant bloom in an underground tuber.", "https://www.kew.org/read-and-watch/the-giant-pongy-plant-titan-arum", null, "2026-10-31"),
    JourneyContent("facts-417", JourneyContentKind.FACT, "Oktopusse besitzen drei Herzen: zwei für die Kiemen und eines für den übrigen Körper.", "Octopuses have three hearts: two for the gills and one for the rest of the body.", "https://ocean.si.edu/ocean-life/invertebrates/octopuses-squids-and-relatives", null, "2026-10-31"),
    JourneyContent("facts-418", JourneyContentKind.FACT, "Das blaue Blut vieler Kopffüßer transportiert Sauerstoff mithilfe von Kupfer statt Eisen.", "Many cephalopods have blue blood carrying oxygen with copper rather than iron.", "https://ocean.si.edu/ocean-life/invertebrates/octopuses-squids-and-relatives", null, "2026-10-31"),
    JourneyContent("facts-419", JourneyContentKind.FACT, "Ein Oktopus besitzt acht Arme; Kalmare besitzen zusätzlich zwei spezialisierte Fangtentakel.", "An octopus has eight arms; squid have two additional specialised feeding tentacles.", "https://ocean.si.edu/ocean-life/invertebrates/octopuses-squids-and-relatives", null, "2026-10-31"),
    JourneyContent("facts-420", JourneyContentKind.FACT, "Kopffüßer können per Rückstoß schwimmen, indem sie Wasser durch einen Trichter ausstoßen.", "Cephalopods can swim by jetting water through a funnel.", "https://ocean.si.edu/ocean-life/invertebrates/octopuses-squids-and-relatives", null, "2026-10-31"),
    JourneyContent("facts-421", JourneyContentKind.FACT, "Oktopusse zerteilen Beute mit einem harten Schnabel zwischen ihren Armen.", "Octopuses cut prey apart using a hard beak between their arms.", "https://ocean.si.edu/ocean-life/invertebrates/octopuses-squids-and-relatives", null, "2026-10-31"),
    JourneyContent("facts-422", JourneyContentKind.FACT, "Spezielle Pigmentzellen helfen vielen Kopffüßern, ihre Hautfarbe rasch zu verändern.", "Special pigment cells help many cephalopods change skin colour rapidly.", "https://ocean.si.edu/ocean-life/invertebrates/octopuses-squids-and-relatives", null, "2026-10-31"),
    JourneyContent("facts-423", JourneyContentKind.FACT, "Pfeilschwanzkrebse sind keine echten Krebse und stehen Spinnentieren verwandtschaftlich näher.", "Horseshoe crabs are not true crabs and are more closely related to arachnids.", "https://ocean.si.edu/ocean-life/invertebrates/creature-feature-amazing-horseshoe-crab", null, "2026-10-31"),
    JourneyContent("facts-424", JourneyContentKind.FACT, "Pfeilschwanzkrebse haben wegen ihres kupferhaltigen Sauerstofftransporters blaues Blut.", "Horseshoe crabs have blue blood because their oxygen carrier contains copper.", "https://ocean.si.edu/ocean-life/invertebrates/creature-feature-amazing-horseshoe-crab", null, "2026-10-31"),
    JourneyContent("facts-425", JourneyContentKind.FACT, "Blutbestandteile von Pfeilschwanzkrebsen werden zum Nachweis bestimmter bakterieller Verunreinigungen genutzt.", "Horseshoe crab blood components are used to detect certain bacterial contaminants.", "https://ocean.si.edu/ocean-life/invertebrates/creature-feature-amazing-horseshoe-crab", null, "2026-10-31"),
    JourneyContent("facts-426", JourneyContentKind.FACT, "Pfeilschwanzkrebs-Eier sind eine wichtige Zwischenmahlzeit für wandernde Küstenvögel.", "Horseshoe crab eggs are an important stopover meal for migrating shorebirds.", "https://ocean.si.edu/ocean-life/invertebrates/creature-feature-amazing-horseshoe-crab", null, "2026-10-31"),
    JourneyContent("facts-427", JourneyContentKind.FACT, "Bei hohen Gezeiten rund um Voll- oder Neumond können sich besonders viele Pfeilschwanzkrebse zum Laichen versammeln.", "High tides around full or new moons can bring large horseshoe crab spawning gatherings.", "https://ocean.si.edu/ocean-life/invertebrates/creature-feature-amazing-horseshoe-crab", null, "2026-10-31"),
    JourneyContent("facts-428", JourneyContentKind.FACT, "Ein Pfeilschwanzkrebs-Weibchen kann jährlich Zehntausende Eier in mehreren Gelegen ablegen.", "A female horseshoe crab can lay tens of thousands of eggs annually in several clusters.", "https://ocean.si.edu/ocean-life/invertebrates/creature-feature-amazing-horseshoe-crab", null, "2026-10-31"),
    JourneyContent("facts-429", JourneyContentKind.FACT, "Korallen sind Tiere, auch wenn manche Kolonien wie blühende Pflanzen aussehen.", "Corals are animals, even when their colonies look like flowering plants.", "https://www.noaa.gov/education/resource-collections/marine-life/coral-reef-ecosystems", null, "2026-10-31"),
    JourneyContent("facts-430", JourneyContentKind.FACT, "Viele tropische Korallen beherbergen Algen im Gewebe und erhalten von ihnen Nährstoffe aus der Photosynthese.", "Many tropical corals house algae in their tissues, receiving nutrients from photosynthesis.", "https://www.noaa.gov/education/resource-collections/marine-life/coral-reef-ecosystems", null, "2026-10-31"),
    JourneyContent("facts-431", JourneyContentKind.FACT, "Auch in kaltem, tiefem und dunklem Wasser können Korallen leben.", "Corals can also live in cold, deep and dark water.", "https://www.noaa.gov/education/resource-collections/marine-life/coral-reef-ecosystems", null, "2026-10-31"),
    JourneyContent("facts-432", JourneyContentKind.FACT, "Tiefseekorallen ohne symbiotische Algen beziehen Energie vor allem aus Plankton und anderem organischen Material.", "Deep-sea corals without symbiotic algae obtain energy mainly from plankton and other organic matter.", "https://www.noaa.gov/education/resource-collections/marine-life/coral-reef-ecosystems", null, "2026-10-31"),
    JourneyContent("facts-433", JourneyContentKind.FACT, "Ungefähr ein Viertel der Meeresfischarten ist auf gesunde Korallenriffe angewiesen.", "Roughly a quarter of marine fish species depend on healthy coral reefs.", "https://www.noaa.gov/education/resource-collections/marine-life/coral-reef-ecosystems", null, "2026-10-31"),
    JourneyContent("facts-434", JourneyContentKind.FACT, "Eine gebleichte Koralle ist nicht automatisch tot: Verbessern sich Bedingungen rechtzeitig, kann sie sich erholen.", "A bleached coral is not automatically dead: it can recover if conditions improve in time.", "https://www.noaa.gov/education/resource-collections/marine-life/coral-reef-ecosystems", null, "2026-10-31"),
    JourneyContent("facts-435", JourneyContentKind.FACT, "Wenn das Meer Kohlendioxid aufnimmt, verändert das seine Chemie und erhöht die Konzentration von Wasserstoffionen.", "Ocean uptake of carbon dioxide changes its chemistry and increases hydrogen ion concentrations.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/ocean-acidification", null, "2026-10-31"),
    JourneyContent("facts-436", JourneyContentKind.FACT, "„Ozeanversauerung“ bedeutet nicht, dass Meerwasser bereits einen pH-Wert unter sieben haben muss.", "Ocean acidification does not mean seawater must already have a pH below seven.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/ocean-acidification", null, "2026-10-31"),
    JourneyContent("facts-437", JourneyContentKind.FACT, "Die pH-Skala ist logarithmisch: Eine ganze Einheit weniger entspricht zehnmal mehr Wasserstoffionen.", "The pH scale is logarithmic: one whole unit lower means ten times more hydrogen ions.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/ocean-acidification", null, "2026-10-31"),
    JourneyContent("facts-438", JourneyContentKind.FACT, "Versauerung macht Carbonat-Ionen knapper, die viele Meerestiere für Schalen und Skelette benötigen.", "Acidification reduces carbonate ions that many marine animals need for shells and skeletons.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/ocean-acidification", null, "2026-10-31"),
    JourneyContent("facts-439", JourneyContentKind.FACT, "Bei entsprechend niedrigem pH können Kalkschalen im Meer sogar beginnen, sich aufzulösen.", "At sufficiently low pH, calcium carbonate shells can start dissolving in seawater.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/ocean-acidification", null, "2026-10-31"),
    JourneyContent("facts-440", JourneyContentKind.FACT, "Auch Austern sind von veränderter Meereschemie betroffen, nicht nur tropische Korallen.", "Oysters are affected by changing ocean chemistry too, not just tropical corals.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/ocean-acidification", null, "2026-10-31"),
    JourneyContent("facts-441", JourneyContentKind.FACT, "Gezeiten sind sehr lange Wellen im Ozean, nicht einfach ein gleichmäßiges Hoch- und Runterschalten des Wassers.", "Tides are very long ocean waves, not a uniform up-and-down water switch.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/tides", null, "2026-10-31"),
    JourneyContent("facts-442", JourneyContentKind.FACT, "Nicht nur der Mond, auch die Sonne trägt zu Ebbe und Flut bei.", "The Sun contributes to tides as well as the Moon.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/tides", null, "2026-10-31"),
    JourneyContent("facts-443", JourneyContentKind.FACT, "Die Gezeitenwirkung erzeugt im vereinfachten Erdmodell zwei Wasserwölbungen auf gegenüberliegenden Seiten.", "In a simplified Earth model, tidal forces create two water bulges on opposite sides.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/tides", null, "2026-10-31"),
    JourneyContent("facts-444", JourneyContentKind.FACT, "Eine Springtide ist nicht an den Frühling gebunden, sondern an die Stellung von Sonne, Erde und Mond.", "Spring tides are unrelated to the season; they depend on Sun, Earth and Moon alignment.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/tides", null, "2026-10-31"),
    JourneyContent("facts-445", JourneyContentKind.FACT, "Bei Nipptiden ist der Unterschied zwischen Hoch- und Niedrigwasser typischerweise kleiner.", "Neap tides typically have a smaller difference between high and low water.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/tides", null, "2026-10-31"),
    JourneyContent("facts-446", JourneyContentKind.FACT, "Form und Lage einer Küste beeinflussen, wann dort Hochwasser eintritt. Mondnähe allein erklärt die Uhrzeit nicht.", "Coastline shape and location affect high-tide timing; lunar proximity alone does not explain it.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/tides", null, "2026-10-31"),
    JourneyContent("facts-447", JourneyContentKind.FACT, "Die Erdrotation lenkt große Meeresströmungen auf der Nordhalbkugel nach rechts und auf der Südhalbkugel nach links ab.", "Earth's rotation deflects large ocean currents rightward in the north and leftward in the south.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/ocean-currents", null, "2026-10-31"),
    JourneyContent("facts-448", JourneyContentKind.FACT, "Wind treibt viele Oberflächenströmungen an; Unterschiede in Temperatur und Salzgehalt bewegen Wasser auch in der Tiefe.", "Wind drives many surface currents; temperature and salinity differences also move deep water.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/ocean-currents", null, "2026-10-31"),
    JourneyContent("facts-449", JourneyContentKind.FACT, "Beim Gefrieren von Meerwasser bleibt viel Salz im umgebenden Wasser zurück, das dadurch dichter werden kann.", "Freezing seawater leaves much salt behind, potentially increasing the surrounding water's density.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/ocean-currents", null, "2026-10-31"),
    JourneyContent("facts-450", JourneyContentKind.FACT, "Die globale Tiefenzirkulation bewegt Wassermassen über Zeiträume von ungefähr tausend Jahren durch die Ozeane.", "Global deep circulation moves water masses through the oceans on roughly thousand-year timescales.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/ocean-currents", null, "2026-10-31"),
    JourneyContent("facts-451", JourneyContentKind.FACT, "Auftriebsströmungen bringen kaltes, nährstoffreiches Tiefenwasser nach oben und unterstützen produktive Fischgründe.", "Upwelling carries cold, nutrient-rich deep water upwards, supporting productive fisheries.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/ocean-currents", null, "2026-10-31"),
    JourneyContent("facts-452", JourneyContentKind.FACT, "Meeresströmungen transportieren auch Larven und beeinflussen so, wo sich Meereslebewesen ansiedeln.", "Ocean currents transport larvae, helping determine where marine life settles.", "https://www.noaa.gov/education/resource-collections/ocean-coasts/ocean-currents", null, "2026-10-31"),
    JourneyContent("facts-453", JourneyContentKind.FACT, "Riesentang ist keine Unterwasser-Baumart, sondern eine große Braunalge.", "Giant kelp is not an underwater tree species but a large brown alga.", "https://oceanservice.noaa.gov/facts/kelp.html", null, "2026-10-31"),
    JourneyContent("facts-454", JourneyContentKind.FACT, "Unter idealen Bedingungen kann Kelp an einem einzigen Tag ungefähr 45 Zentimeter wachsen.", "Under ideal conditions, kelp can grow roughly 45 centimetres in one day.", "https://oceanservice.noaa.gov/facts/kelp.html", null, "2026-10-31"),
    JourneyContent("facts-455", JourneyContentKind.FACT, "Kelpwälder wachsen meist in kühlem, nährstoffreichem Küstenwasser.", "Kelp forests usually grow in cool, nutrient-rich coastal water.", "https://oceanservice.noaa.gov/facts/kelp.html", null, "2026-10-31"),
    JourneyContent("facts-456", JourneyContentKind.FACT, "Weil Kelp Licht braucht, stehen seine Unterwasserwälder überwiegend in relativ flachem Wasser.", "Because kelp needs light, its underwater forests mostly grow in relatively shallow water.", "https://oceanservice.noaa.gov/facts/kelp.html", null, "2026-10-31"),
    JourneyContent("facts-457", JourneyContentKind.FACT, "Dichte Tangblätter bieten vielen Jungfischen Schutz vor Fressfeinden und rauem Wasser.", "Dense kelp blades shelter many young fish from predators and rough water.", "https://oceanservice.noaa.gov/facts/kelp.html", null, "2026-10-31"),
    JourneyContent("facts-458", JourneyContentKind.FACT, "Auch Unterwasserwälder kennen Jahreszeiten: Winterstürme können Kelp losreißen und Bestände stark verändern.", "Underwater forests have seasons too: winter storms can tear kelp loose and reshape them.", "https://oceanservice.noaa.gov/facts/kelp.html", null, "2026-10-31"),
    JourneyContent("facts-459", JourneyContentKind.FACT, "Mangroven sind keine einzelne Baumart, sondern eine Gruppe verschiedener salztoleranter Küstenbäume und Sträucher.", "Mangroves are not one tree species but a group of salt-tolerant coastal trees and shrubs.", "https://oceanservice.noaa.gov/facts/mangroves.html", null, "2026-10-31"),
    JourneyContent("facts-460", JourneyContentKind.FACT, "Viele Mangroven sehen durch ihre Stelzwurzeln aus, als stünden sie über dem Wasser auf Beinen.", "Many mangroves look as though they stand above water on stilt-like prop roots.", "https://oceanservice.noaa.gov/facts/mangroves.html", null, "2026-10-31"),
    JourneyContent("facts-461", JourneyContentKind.FACT, "Mangroven können in sauerstoffarmen Schlammböden wachsen, in denen viele andere Bäume scheitern.", "Mangroves can grow in oxygen-poor mud where many other trees cannot.", "https://oceanservice.noaa.gov/facts/mangroves.html", null, "2026-10-31"),
    JourneyContent("facts-462", JourneyContentKind.FACT, "Mangrovenwurzeln bremsen Gezeitenwasser ab, sodass sich Schwebstoffe absetzen können.", "Mangrove roots slow tidal water, allowing suspended sediments to settle.", "https://oceanservice.noaa.gov/facts/mangroves.html", null, "2026-10-31"),
    JourneyContent("facts-463", JourneyContentKind.FACT, "Mangrovenwälder schützen Küsten, indem sie Erosion durch Wellen und Strömungen verringern.", "Mangrove forests protect coasts by reducing erosion from waves and currents.", "https://oceanservice.noaa.gov/facts/mangroves.html", null, "2026-10-31"),
    JourneyContent("facts-464", JourneyContentKind.FACT, "Das Wurzelgewirr von Mangroven bietet Fischen Verstecke vor Fressfeinden.", "Tangled mangrove roots provide fish with hiding places from predators.", "https://oceanservice.noaa.gov/facts/mangroves.html", null, "2026-10-31"),
    JourneyContent("facts-465", JourneyContentKind.FACT, "An Tiefseequellen können ganze Lebensgemeinschaften ohne Sonnenlicht von chemischer Energie leben.", "Entire deep-sea vent communities can live on chemical energy without sunlight.", "https://www.whoi.edu/ocean-learning-hub/ocean-topics/how-the-ocean-works/seafloor-below/hydrothermal-vents/", null, "2026-10-31"),
    JourneyContent("facts-466", JourneyContentKind.FACT, "Hydrothermale Quellen entstehen, wenn Meerwasser in die Erdkruste eindringt und von heißem Gestein erwärmt wird.", "Hydrothermal vents form when seawater enters Earth's crust and is heated by hot rock.", "https://www.whoi.edu/ocean-learning-hub/ocean-topics/how-the-ocean-works/seafloor-below/hydrothermal-vents/", null, "2026-10-31"),
    JourneyContent("facts-467", JourneyContentKind.FACT, "Wasser aus Tiefseequellen kann etwa 400 Grad Celsius erreichen, ohne wegen des hohen Drucks zu sieden.", "Deep-sea vent water can reach about 400 degrees Celsius without boiling under the high pressure.", "https://www.whoi.edu/ocean-learning-hub/ocean-topics/how-the-ocean-works/seafloor-below/hydrothermal-vents/", null, "2026-10-31"),
    JourneyContent("facts-468", JourneyContentKind.FACT, "Die dunklen „Rauchwolken“ schwarzer Raucher bestehen aus ausfallenden Mineralpartikeln, nicht aus Verbrennungsrauch.", "Black smokers' dark clouds contain precipitating mineral particles, not combustion smoke.", "https://www.whoi.edu/ocean-learning-hub/ocean-topics/how-the-ocean-works/seafloor-below/hydrothermal-vents/", null, "2026-10-31"),
    JourneyContent("facts-469", JourneyContentKind.FACT, "Mikroben an Tiefseequellen können Schwefelwasserstoff als Energiequelle für die Bildung organischer Stoffe nutzen.", "Deep-sea vent microbes can use hydrogen sulfide as energy for producing organic matter.", "https://www.whoi.edu/ocean-learning-hub/ocean-topics/how-the-ocean-works/seafloor-below/hydrothermal-vents/", null, "2026-10-31"),
    JourneyContent("facts-470", JourneyContentKind.FACT, "Hydrothermale Lebensgemeinschaften wurden erst 1977 entdeckt und veränderten das Bild lebensfreundlicher Umgebungen.", "Hydrothermal vent communities were discovered only in 1977, changing ideas about habitable environments.", "https://www.whoi.edu/ocean-learning-hub/ocean-topics/how-the-ocean-works/seafloor-below/hydrothermal-vents/", null, "2026-10-31"),
    JourneyContent("facts-471", JourneyContentKind.FACT, "Gletscher sind fest, fließen unter ihrem eigenen Gewicht aber trotzdem langsam bergab.", "Glaciers are solid yet still flow slowly downhill under their own weight.", "https://www.usgs.gov/water-science-school/science/glaciers-and-icecaps", null, "2026-10-31"),
    JourneyContent("facts-472", JourneyContentKind.FACT, "Gletschereis entsteht, wenn sich über Jahre mehr Schnee ansammelt, als wieder abschmilzt.", "Glacial ice forms when snow accumulates over years faster than it melts.", "https://www.usgs.gov/water-science-school/science/glaciers-and-icecaps", null, "2026-10-31"),
    JourneyContent("facts-473", JourneyContentKind.FACT, "Gletscher können Täler zu breiten U-Formen ausschleifen.", "Glaciers can carve valleys into broad U shapes.", "https://www.usgs.gov/water-science-school/science/glaciers-and-icecaps", null, "2026-10-31"),
    JourneyContent("facts-474", JourneyContentKind.FACT, "Unter Teilen des grönländischen Eisschilds hat das Eisgewicht den Untergrund bis unter den Meeresspiegel gedrückt.", "Ice weight has pushed bedrock below sea level beneath parts of Greenland's ice sheet.", "https://www.usgs.gov/water-science-school/science/glaciers-and-icecaps", null, "2026-10-31"),
    JourneyContent("facts-475", JourneyContentKind.FACT, "In manchen arktischen Eiskappen ist das unterste Eis über hunderttausend Jahre alt.", "The oldest basal ice in some Arctic ice caps is over a hundred thousand years old.", "https://www.usgs.gov/water-science-school/science/glaciers-and-icecaps", null, "2026-10-31"),
    JourneyContent("facts-476", JourneyContentKind.FACT, "Während der letzten großen Vereisung lag der Meeresspiegel ungefähr 120 Meter tiefer als heute.", "During the last major glaciation, sea level was roughly 120 metres lower than today.", "https://www.usgs.gov/water-science-school/science/glaciers-and-icecaps", null, "2026-10-31"),
    JourneyContent("facts-477", JourneyContentKind.FACT, "Flüssiges Süßwasser ist bei ungefähr vier Grad Celsius am dichtesten, nicht direkt am Gefrierpunkt.", "Liquid freshwater is densest at roughly four degrees Celsius, not at freezing.", "https://www.usgs.gov/water-science-school/science/water-density", null, "2026-10-31"),
    JourneyContent("facts-478", JourneyContentKind.FACT, "Beim Gefrieren vergrößert Wasser sein Volumen ungefähr um neun Prozent.", "Water expands by roughly nine percent when it freezes.", "https://www.usgs.gov/water-science-school/science/water-density", null, "2026-10-31"),
    JourneyContent("facts-479", JourneyContentKind.FACT, "Im Eis hält eine geordnete Kristallstruktur Wassermoleküle weiter auseinander als im flüssigen Wasser.", "In ice, an ordered crystal structure spaces water molecules farther apart than in liquid water.", "https://www.usgs.gov/water-science-school/science/water-density", null, "2026-10-31"),
    JourneyContent("facts-480", JourneyContentKind.FACT, "Bei einem schwimmenden Eisberg liegt typischerweise der weitaus größte Teil unter Wasser.", "Most of a floating iceberg typically lies beneath the water.", "https://www.usgs.gov/water-science-school/science/water-density", null, "2026-10-31"),
    JourneyContent("facts-481", JourneyContentKind.FACT, "Gelöstes Salz macht Meerwasser dichter als reines Wasser bei vergleichbaren Bedingungen.", "Dissolved salt makes seawater denser than pure water under comparable conditions.", "https://www.usgs.gov/water-science-school/science/water-density", null, "2026-10-31"),
    JourneyContent("facts-482", JourneyContentKind.FACT, "Die Dichteanomalie des Wassers hilft, dass ein winterlicher See nicht einfach von unten nach oben zufriert.", "Water's density anomaly helps prevent a winter lake simply freezing from bottom to top.", "https://www.usgs.gov/water-science-school/science/water-density", null, "2026-10-31"),
    JourneyContent("facts-483", JourneyContentKind.FACT, "Küchenpapier kann Wasser nach oben saugen, obwohl die Schwerkraft nach unten wirkt.", "Paper towels can wick water upwards despite gravity pulling downwards.", "https://www.usgs.gov/water-science-school/science/capillary-action-and-water", null, "2026-10-31"),
    JourneyContent("facts-484", JourneyContentKind.FACT, "In engeren Glasröhrchen steigt Wasser durch Kapillarkräfte höher als in breiteren.", "Capillary forces lift water higher in narrower glass tubes than wider ones.", "https://www.usgs.gov/water-science-school/science/capillary-action-and-water", null, "2026-10-31"),
    JourneyContent("facts-485", JourneyContentKind.FACT, "Wasser haftet an Glas und bildet dadurch am Rand oft eine nach oben gekrümmte Oberfläche.", "Water adheres to glass, often creating an upward-curving surface at the edge.", "https://www.usgs.gov/water-science-school/science/capillary-action-and-water", null, "2026-10-31"),
    JourneyContent("facts-486", JourneyContentKind.FACT, "Kapillarkräfte helfen Wasser, durch kleine Poren in Materialien wie Erde oder Stoff zu wandern.", "Capillary forces help water move through tiny pores in soil or fabric.", "https://www.usgs.gov/water-science-school/science/capillary-action-and-water", null, "2026-10-31"),
    JourneyContent("facts-487", JourneyContentKind.FACT, "Kapillarkraft allein reicht nicht, um Wasser bis in die Krone eines hohen Baumes zu ziehen.", "Capillary action alone cannot pull water all the way into a tall tree's crown.", "https://www.usgs.gov/water-science-school/science/capillary-action-and-water", null, "2026-10-31"),
    JourneyContent("facts-488", JourneyContentKind.FACT, "Dass Wasser zusammenhängende Tropfen bildet, hängt mit der Anziehung zwischen seinen Molekülen zusammen.", "Water forms cohesive drops because its molecules attract one another.", "https://www.usgs.gov/water-science-school/science/capillary-action-and-water", null, "2026-10-31"),
    JourneyContent("facts-489", JourneyContentKind.FACT, "Ein Regenbogen ist eigentlich ein Kreis. Vom Boden sehen wir meist nur den oberen Teil.", "A rainbow is actually a circle; from the ground we usually see only its upper part.", "https://www.nesdis.noaa.gov/about/k-12-education/optical-phenomena/what-causes-rainbow", null, "2026-10-31"),
    JourneyContent("facts-490", JourneyContentKind.FACT, "Ein Regenbogen liegt für seinen Betrachter auf der sonnenabgewandten Seite des Himmels.", "For its observer, a rainbow appears in the sky opposite the Sun.", "https://www.nesdis.noaa.gov/about/k-12-education/optical-phenomena/what-causes-rainbow", null, "2026-10-31"),
    JourneyContent("facts-491", JourneyContentKind.FACT, "Beim doppelten Regenbogen ist die Farbreihenfolge des äußeren Bogens umgekehrt.", "In a double rainbow, the outer bow has its colours reversed.", "https://www.nesdis.noaa.gov/about/k-12-education/optical-phenomena/what-causes-rainbow", null, "2026-10-31"),
    JourneyContent("facts-492", JourneyContentKind.FACT, "Der zweite Regenbogen entsteht durch eine zusätzliche Reflexion des Lichts innerhalb der Regentropfen.", "The secondary rainbow comes from an additional light reflection inside raindrops.", "https://www.nesdis.noaa.gov/about/k-12-education/optical-phenomena/what-causes-rainbow", null, "2026-10-31"),
    JourneyContent("facts-493", JourneyContentKind.FACT, "Regenbogenfarben werden nicht vom Wasser erzeugt: Sie sind bereits im Sonnenlicht enthalten.", "Rainbow colours are not created by water: they are already present in sunlight.", "https://www.nesdis.noaa.gov/about/k-12-education/optical-phenomena/what-causes-rainbow", null, "2026-10-31"),
    JourneyContent("facts-494", JourneyContentKind.FACT, "Ein Regenbogen besitzt keinen festen Ort, den man erreichen könnte; seine Erscheinung hängt vom Beobachter ab.", "A rainbow has no fixed place to reach; its appearance depends on the observer.", "https://www.nesdis.noaa.gov/about/k-12-education/optical-phenomena/what-causes-rainbow", null, "2026-10-31"),
    JourneyContent("facts-495", JourneyContentKind.FACT, "Das Epizentrum liegt an der Erdoberfläche; der eigentliche Erdbebenherd befindet sich darunter.", "An epicentre is on Earth's surface; the earthquake's actual origin lies beneath it.", "https://www.usgs.gov/programs/earthquake-hazards/science-earthquakes", null, "2026-10-31"),
    JourneyContent("facts-496", JourneyContentKind.FACT, "P-Wellen eines Erdbebens kommen früher an als die langsameren S-Wellen.", "An earthquake's P waves arrive before its slower S waves.", "https://www.usgs.gov/programs/earthquake-hazards/science-earthquakes", null, "2026-10-31"),
    JourneyContent("facts-497", JourneyContentKind.FACT, "Aus dem Zeitabstand zwischen P- und S-Wellen lässt sich die Entfernung zum Beben abschätzen.", "The delay between P and S waves helps estimate an earthquake's distance.", "https://www.usgs.gov/programs/earthquake-hazards/science-earthquakes", null, "2026-10-31"),
    JourneyContent("facts-498", JourneyContentKind.FACT, "Nachbeben eines starken Erdbebens können noch Monate oder sogar Jahre später auftreten.", "Aftershocks from a major earthquake can continue for months or even years.", "https://www.usgs.gov/programs/earthquake-hazards/science-earthquakes", null, "2026-10-31"),
    JourneyContent("facts-499", JourneyContentKind.FACT, "Ob ein kleines Beben ein Vorbeben war, lässt sich erst nach einem folgenden größeren Beben erkennen.", "A small quake can only be identified as a foreshock after a larger one follows.", "https://www.usgs.gov/programs/earthquake-hazards/science-earthquakes", null, "2026-10-31"),
    JourneyContent("facts-500", JourneyContentKind.FACT, "Ein Erdbeben hat eine Magnitude, aber seine gefühlte Intensität unterscheidet sich von Ort zu Ort.", "An earthquake has one magnitude, but its experienced intensity varies by location.", "https://www.usgs.gov/programs/earthquake-hazards/science-earthquakes", null, "2026-10-31"),
    JourneyContent("facts-501", JourneyContentKind.FACT, "Nicht jeder Vulkan bildet einen Kegel: Manche entstehen als breite Schilde oder große Einsturzmulden.", "Not every volcano forms a cone: some form broad shields or large collapse depressions.", "https://www.nps.gov/subjects/volcanoes/anatomy-of-a-volcano.htm", null, "2026-10-31"),
    JourneyContent("facts-502", JourneyContentKind.FACT, "Schildvulkane wachsen durch viele dünnflüssige Lavaströme und besitzen deshalb oft sanfte Hänge.", "Shield volcanoes grow from many fluid lava flows and consequently often have gentle slopes.", "https://www.nps.gov/subjects/volcanoes/anatomy-of-a-volcano.htm", null, "2026-10-31"),
    JourneyContent("facts-503", JourneyContentKind.FACT, "Manche Vulkane brechen typischerweise nur einmal aus; andere sind über viele Ausbrüche hinweg aktiv.", "Some volcanoes typically erupt only once; others remain active through many eruptions.", "https://www.nps.gov/subjects/volcanoes/anatomy-of-a-volcano.htm", null, "2026-10-31"),
    JourneyContent("facts-504", JourneyContentKind.FACT, "Ein Vulkangebiet kann über lange Zeit aktiv bleiben, obwohl jeder einzelne Schlot nur einmal ausbricht.", "A volcanic field can remain active for ages even when individual vents erupt only once.", "https://www.nps.gov/subjects/volcanoes/anatomy-of-a-volcano.htm", null, "2026-10-31"),
    JourneyContent("facts-505", JourneyContentKind.FACT, "Maare sind Vulkanformen, deren Mulden unterhalb des umgebenden Geländes liegen.", "Maars are volcanic landforms whose depressions lie below the surrounding terrain.", "https://www.nps.gov/subjects/volcanoes/anatomy-of-a-volcano.htm", null, "2026-10-31"),
    JourneyContent("facts-506", JourneyContentKind.FACT, "Eine Caldera kann entstehen, wenn der Untergrund über einer Magmakammer zusammenbricht.", "A caldera can form when ground collapses above a magma chamber.", "https://www.nps.gov/subjects/volcanoes/anatomy-of-a-volcano.htm", null, "2026-10-31"),
    JourneyContent("facts-507", JourneyContentKind.FACT, "Ein Plutotag dauert etwa 153 Stunden. Dort wäre eine Arbeitswoche noch vor dem nächsten Sonnenaufgang vorbei.", "A Pluto day lasts about 153 hours: longer than a standard working week.", "https://science.nasa.gov/dwarf-planets/pluto/facts/", null, "2026-10-31"),
    JourneyContent("facts-508", JourneyContentKind.FACT, "Pluto braucht für einen Umlauf um die Sonne ungefähr 248 Erdenjahre.", "Pluto takes roughly 248 Earth years to orbit the Sun.", "https://science.nasa.gov/dwarf-planets/pluto/facts/", null, "2026-10-31"),
    JourneyContent("facts-509", JourneyContentKind.FACT, "Pluto besitzt fünf bekannte Monde; der größte heißt Charon.", "Pluto has five known moons; the largest is Charon.", "https://science.nasa.gov/dwarf-planets/pluto/facts/", null, "2026-10-31"),
    JourneyContent("facts-510", JourneyContentKind.FACT, "Auf Pluto gibt es Berge aus Wassereis. Bei seinen Temperaturen kann Eis wie Gestein wirken.", "Pluto has water-ice mountains; at its temperatures, ice can behave like rock.", "https://science.nasa.gov/dwarf-planets/pluto/facts/", null, "2026-10-31"),
    JourneyContent("facts-511", JourneyContentKind.FACT, "Plutos dünne Atmosphäre enthält unter anderem Stickstoff, Methan und Kohlenmonoxid.", "Pluto's thin atmosphere includes nitrogen, methane and carbon monoxide.", "https://science.nasa.gov/dwarf-planets/pluto/facts/", null, "2026-10-31"),
    JourneyContent("facts-512", JourneyContentKind.FACT, "Plutos auffälliges helles Oberflächengebiet sieht auf Bildern wie ein riesiges Herz aus.", "Pluto's conspicuous bright surface region looks like a giant heart in images.", "https://science.nasa.gov/dwarf-planets/pluto/facts/", null, "2026-10-31"),
    JourneyContent("facts-513", JourneyContentKind.FACT, "Ceres ist das größte Objekt im Asteroidengürtel zwischen Mars und Jupiter.", "Ceres is the largest object in the asteroid belt between Mars and Jupiter.", "https://science.nasa.gov/dwarf-planets/ceres/facts/", null, "2026-10-31"),
    JourneyContent("facts-514", JourneyContentKind.FACT, "Ceres ist der einzige Zwergplanet im inneren Sonnensystem.", "Ceres is the only dwarf planet in the inner solar system.", "https://science.nasa.gov/dwarf-planets/ceres/facts/", null, "2026-10-31"),
    JourneyContent("facts-515", JourneyContentKind.FACT, "Giuseppe Piazzi entdeckte Ceres bereits 1801, lange vor dem Raumfahrtzeitalter.", "Giuseppe Piazzi discovered Ceres in 1801, long before the space age.", "https://science.nasa.gov/dwarf-planets/ceres/facts/", null, "2026-10-31"),
    JourneyContent("facts-516", JourneyContentKind.FACT, "Ceres war der erste Zwergplanet, den eine Raumsonde besuchte: Dawn erreichte ihn 2015.", "Ceres was the first dwarf planet visited by a spacecraft: Dawn arrived in 2015.", "https://science.nasa.gov/dwarf-planets/ceres/facts/", null, "2026-10-31"),
    JourneyContent("facts-517", JourneyContentKind.FACT, "Nach Schätzungen könnte ungefähr ein Viertel der Ceres-Masse aus Wasser bestehen.", "Estimates suggest water could account for roughly a quarter of Ceres's mass.", "https://science.nasa.gov/dwarf-planets/ceres/facts/", null, "2026-10-31"),
    JourneyContent("facts-518", JourneyContentKind.FACT, "Helle Flecken auf Ceres enthalten Salze. Sie bestehen nicht einfach aus gewöhnlichem Speisesalz.", "Bright spots on Ceres contain salts, rather than simply ordinary table salt.", "https://science.nasa.gov/dwarf-planets/ceres/facts/", null, "2026-10-31"),
    JourneyContent("facts-519", JourneyContentKind.FACT, "Starke Indizien sprechen für einen salzigen Ozean unter der Eiskruste des Jupitermonds Europa.", "Strong evidence suggests a salty ocean beneath Jupiter's moon Europa's ice shell.", "https://science.nasa.gov/jupiter/jupiter-moons/europa/europa-facts/", null, "2026-10-31"),
    JourneyContent("facts-520", JourneyContentKind.FACT, "Europas vermuteter Ozean könnte mehr Wasser enthalten als alle irdischen Ozeane zusammen.", "Europa's suspected ocean could contain more water than all Earth's oceans combined.", "https://science.nasa.gov/jupiter/jupiter-moons/europa/europa-facts/", null, "2026-10-31"),
    JourneyContent("facts-521", JourneyContentKind.FACT, "Europas äußere Eisschicht wird auf ungefähr 15 bis 25 Kilometer Dicke geschätzt.", "Europa's outer ice shell is estimated to be roughly 15 to 25 kilometres thick.", "https://science.nasa.gov/jupiter/jupiter-moons/europa/europa-facts/", null, "2026-10-31"),
    JourneyContent("facts-522", JourneyContentKind.FACT, "Europa besitzt eine extrem dünne Sauerstoffatmosphäre, die für Menschen nicht zum Atmen reicht.", "Europa has an extremely thin oxygen atmosphere, far too tenuous for humans to breathe.", "https://science.nasa.gov/jupiter/jupiter-moons/europa/europa-facts/", null, "2026-10-31"),
    JourneyContent("facts-523", JourneyContentKind.FACT, "Der Jupitermond Europa ist etwas kleiner als unser Erdmond.", "Jupiter's moon Europa is slightly smaller than Earth's Moon.", "https://science.nasa.gov/jupiter/jupiter-moons/europa/europa-facts/", null, "2026-10-31"),
    JourneyContent("facts-524", JourneyContentKind.FACT, "Europa umrundet Jupiter in nur ungefähr dreieinhalb Erdtagen.", "Europa orbits Jupiter in only about three and a half Earth days.", "https://science.nasa.gov/jupiter/jupiter-moons/europa/europa-facts/", null, "2026-10-31"),
    JourneyContent("facts-525", JourneyContentKind.FACT, "Auf Titan gibt es Regen, Flüsse und Seen aus flüssigem Methan und Ethan statt aus Wasser.", "Titan has rain, rivers and lakes of liquid methane and ethane instead of water.", "https://science.nasa.gov/saturn/moons/titan/facts/", null, "2026-10-31"),
    JourneyContent("facts-526", JourneyContentKind.FACT, "Titan ist der einzige Mond im Sonnensystem mit einer dichten Atmosphäre.", "Titan is the only moon in the solar system with a dense atmosphere.", "https://science.nasa.gov/saturn/moons/titan/facts/", null, "2026-10-31"),
    JourneyContent("facts-527", JourneyContentKind.FACT, "Titans Atmosphäre besteht wie die der Erde überwiegend aus Stickstoff.", "Like Earth's, Titan's atmosphere consists mainly of nitrogen.", "https://science.nasa.gov/saturn/moons/titan/facts/", null, "2026-10-31"),
    JourneyContent("facts-528", JourneyContentKind.FACT, "Titan ist größer als der Planet Merkur, besitzt aber deutlich weniger Masse.", "Titan is larger than Mercury but has substantially less mass.", "https://science.nasa.gov/saturn/moons/titan/facts/", null, "2026-10-31"),
    JourneyContent("facts-529", JourneyContentKind.FACT, "Auf Titans eiskalter Oberfläche kann Wassereis eine ähnliche Rolle spielen wie Gestein auf der Erde.", "On Titan's frigid surface, water ice can play a role similar to rock on Earth.", "https://science.nasa.gov/saturn/moons/titan/facts/", null, "2026-10-31"),
    JourneyContent("facts-530", JourneyContentKind.FACT, "Christiaan Huygens entdeckte Titan schon 1655 mit einem Teleskop.", "Christiaan Huygens discovered Titan with a telescope back in 1655.", "https://science.nasa.gov/saturn/moons/titan/facts/", null, "2026-10-31"),
    JourneyContent("facts-531", JourneyContentKind.FACT, "Enceladus besitzt eine besonders helle Eisoberfläche, die einen großen Teil des Sonnenlichts zurückwirft.", "Enceladus has an especially bright icy surface reflecting much of the sunlight.", "https://science.nasa.gov/saturn/moons/enceladus/", null, "2026-10-31"),
    JourneyContent("facts-532", JourneyContentKind.FACT, "Aus Enceladus schießen Fontänen aus Wasserdampf und Eispartikeln ins All.", "Enceladus ejects fountains of water vapour and ice particles into space.", "https://science.nasa.gov/saturn/moons/enceladus/", null, "2026-10-31"),
    JourneyContent("facts-533", JourneyContentKind.FACT, "Unter dem Eis von Enceladus liegt ein globaler Ozean aus salzigem Wasser.", "A global saltwater ocean lies beneath Enceladus's ice.", "https://science.nasa.gov/saturn/moons/enceladus/", null, "2026-10-31"),
    JourneyContent("facts-534", JourneyContentKind.FACT, "Die Fontänen von Enceladus versorgen Saturns E-Ring mit Material.", "Enceladus's fountains supply material to Saturn's E ring.", "https://science.nasa.gov/saturn/moons/enceladus/", null, "2026-10-31"),
    JourneyContent("facts-535", JourneyContentKind.FACT, "Die auffälligen warmen Spalten am Südpol von Enceladus heißen informell „Tigerstreifen“.", "Enceladus's distinctive warm south-polar fractures are informally called tiger stripes.", "https://science.nasa.gov/saturn/moons/enceladus/", null, "2026-10-31"),
    JourneyContent("facts-536", JourneyContentKind.FACT, "Enceladus ist nur ungefähr 500 Kilometer breit und kann trotzdem einen unterirdischen Ozean besitzen.", "Enceladus is only roughly 500 kilometres across yet can harbour a subsurface ocean.", "https://science.nasa.gov/saturn/moons/enceladus/", null, "2026-10-31"),
    JourneyContent("facts-537", JourneyContentKind.FACT, "Kometenkerne bestehen aus gefrorenen Gasen, Eis, Staub und Gesteinsmaterial.", "Comet nuclei consist of frozen gases, ice, dust and rocky material.", "https://science.nasa.gov/solar-system/comets/facts/", null, "2026-10-31"),
    JourneyContent("facts-538", JourneyContentKind.FACT, "Nahe der Sonne kann ein Komet eine vorübergehende Gashülle bilden, die Koma heißt.", "Near the Sun, a comet can develop a temporary gas envelope called a coma.", "https://science.nasa.gov/solar-system/comets/facts/", null, "2026-10-31"),
    JourneyContent("facts-539", JourneyContentKind.FACT, "Ein Kometenschweif zeigt im Allgemeinen von der Sonne weg, nicht einfach entgegen der Flugrichtung.", "A comet tail generally points away from the Sun, not simply opposite its travel direction.", "https://science.nasa.gov/solar-system/comets/facts/", null, "2026-10-31"),
    JourneyContent("facts-540", JourneyContentKind.FACT, "Kometen können getrennte Staub- und Ionenschweife besitzen.", "Comets can have separate dust and ion tails.", "https://science.nasa.gov/solar-system/comets/facts/", null, "2026-10-31"),
    JourneyContent("facts-541", JourneyContentKind.FACT, "Sonnenwind und Strahlungsdruck helfen dabei, die Schweife von Kometen zu formen.", "Solar wind and radiation pressure help shape comet tails.", "https://science.nasa.gov/solar-system/comets/facts/", null, "2026-10-31"),
    JourneyContent("facts-542", JourneyContentKind.FACT, "Viele kurzperiodische Kometen stammen aus dem Kuipergürtel jenseits der Neptunbahn.", "Many short-period comets originate in the Kuiper Belt beyond Neptune's orbit.", "https://science.nasa.gov/solar-system/comets/facts/", null, "2026-10-31"),
    JourneyContent("facts-543", JourneyContentKind.FACT, "Sehr langperiodische Kometen können aus der weit entfernten Oortschen Wolke kommen.", "Very long-period comets can come from the distant Oort Cloud.", "https://science.nasa.gov/solar-system/comets/facts/", null, "2026-10-31"),
    JourneyContent("facts-544", JourneyContentKind.FACT, "Alle Asteroiden zusammen besitzen weniger Masse als unser Mond.", "All asteroids combined have less mass than Earth's Moon.", "https://science.nasa.gov/solar-system/asteroids/facts/", null, "2026-10-31"),
    JourneyContent("facts-545", JourneyContentKind.FACT, "Der Hauptgürtel der Asteroiden liegt zwischen den Umlaufbahnen von Mars und Jupiter.", "The main asteroid belt lies between the orbits of Mars and Jupiter.", "https://science.nasa.gov/solar-system/asteroids/facts/", null, "2026-10-31"),
    JourneyContent("facts-546", JourneyContentKind.FACT, "Viele Asteroiden des C-Typs sind sehr dunkel und enthalten kohlenstoffreiches Material.", "Many C-type asteroids are very dark and contain carbon-rich material.", "https://science.nasa.gov/solar-system/asteroids/facts/", null, "2026-10-31"),
    JourneyContent("facts-547", JourneyContentKind.FACT, "Asteroiden des S-Typs enthalten vor allem Silikatmaterial sowie Nickel und Eisen.", "S-type asteroids contain mainly silicate material along with nickel and iron.", "https://science.nasa.gov/solar-system/asteroids/facts/", null, "2026-10-31"),
    JourneyContent("facts-548", JourneyContentKind.FACT, "Asteroiden des M-Typs sind besonders metallreich, unter anderem an Nickel und Eisen.", "M-type asteroids are especially rich in metals including nickel and iron.", "https://science.nasa.gov/solar-system/asteroids/facts/", null, "2026-10-31"),
    JourneyContent("facts-549", JourneyContentKind.FACT, "Trojanische Asteroiden teilen sich die Umlaufbahn eines Planeten, ohne dessen Monde zu sein.", "Trojan asteroids share a planet's orbit without being its moons.", "https://science.nasa.gov/solar-system/asteroids/facts/", null, "2026-10-31"),
    JourneyContent("satire-141", JourneyContentKind.SATIRE, "Die DB-App ist mein Escape Room. Das Rätsel lautet: Welcher dieser Züge existiert?", "The rail app is my escape room. The puzzle: which of these trains exists?", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-142", JourneyContentKind.SATIRE, "Am Bahnsteig lerne ich Vokabeln: „in Kürze“ ist offenbar keine Zeitangabe.", "The platform teaches vocabulary: shortly apparently isn't a unit of time.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-143", JourneyContentKind.SATIRE, "Mein ICE spielt Verstecken. Ich finde nur seine Verspätungsanzeige.", "My express train is playing hide-and-seek. I've only found its delay display.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-144", JourneyContentKind.SATIRE, "Die Deutsche Bahn bietet Zeitreisen. Vor allem vom geplanten Feierabend in den tatsächlichen.", "German rail offers time travel, mainly from my planned evening off to my actual one.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-145", JourneyContentKind.SATIRE, "Ich wollte spontan sein. Jetzt bin ich spontan am falschen Gleis.", "I wanted to be spontaneous. Now I'm spontaneously on the wrong platform.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-146", JourneyContentKind.SATIRE, "Der Fahrplan und ich führen eine Fernbeziehung. Wir sehen uns selten in der Realität.", "The timetable and I are in a long-distance relationship. We rarely meet in real life.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-147", JourneyContentKind.SATIRE, "„Bitte achten Sie auf die Durchsage.“ Die Durchsage: ein Saxofonsolo durch einen Staubsauger.", "Please listen to the announcement. The announcement: a saxophone solo through a vacuum cleaner.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-148", JourneyContentKind.SATIRE, "Meine Sitzplatzreservierung hat heute mehr Reisefreiheit als ich. Sie ist in einem anderen Wagen.", "My seat reservation has more freedom to travel than I do today. It's in another coach.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-149", JourneyContentKind.SATIRE, "Das Bordbistro hat geschlossen. Mein Hunger fährt als Ersatzverkehr weiter.", "The buffet car is closed. My hunger continues on a replacement service.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-150", JourneyContentKind.SATIRE, "Ich sammle keine Bonuspunkte mehr. Ich sammle alternative Routen nach Hause.", "I no longer collect reward points. I collect alternative routes home.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-151", JourneyContentKind.SATIRE, "Die Bahnsteiganzeige ist mein Tamagotchi: kurz nicht hingesehen, schon braucht sie wieder Aufmerksamkeit.", "The departure board is my Tamagotchi: look away briefly and it needs attention again.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-152", JourneyContentKind.SATIRE, "Meine Verbindung enthält jetzt drei Umstiege und einen kleinen Charakterbildungsroman.", "My connection now includes three changes and a short character-building novel.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-153", JourneyContentKind.SATIRE, "DB-Fitnessprogramm: Erst Treppen sprinten, dann im stehenden Zug Balance trainieren.", "Railway fitness programme: sprint up stairs, then practise balance on a standing-room train.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-154", JourneyContentKind.SATIRE, "Ich bin nicht zu früh los. Ich habe dem Schicksal nur einen Vorsprung gegeben.", "I didn't leave too early. I just gave fate a head start.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-155", JourneyContentKind.SATIRE, "Das Gleis wurde geändert. Mein Kaffee hat den Richtungswechsel noch nicht verarbeitet.", "The platform changed. My coffee hasn't processed the turn yet.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-156", JourneyContentKind.SATIRE, "Meine Bahnreise hat einen Plot Twist. Leider war das schon der vierte vor dem Frühstück.", "My train journey has a plot twist. Unfortunately, it's the fourth before breakfast.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-157", JourneyContentKind.SATIRE, "Ich liebe Überraschungen. Bei Gleisnummern arbeite ich noch daran.", "I love surprises. I'm still working on loving surprise platform numbers.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-158", JourneyContentKind.SATIRE, "Der Zug ist heute ein abstraktes Konzept mit Zugnummer.", "Today's train is an abstract concept with a service number.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-159", JourneyContentKind.SATIRE, "„Endet hier.“ Mein Zug und meine sorgfältig gefalteten Pläne teilen sich einen Satz.", "Terminates here. My train and my carefully folded plans share a sentence.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-160", JourneyContentKind.SATIRE, "Die Deutsche Bahn macht aus Pendlern Logistiker. Ausbildung direkt am offenen Anschluss.", "German rail turns commuters into logistics planners, with hands-on connection training.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-161", JourneyContentKind.SATIRE, "Der Ersatzbus hat keinen Speisewagen. Meine Ansprüche fahren heute regional.", "The replacement bus has no dining car. My expectations are travelling local today.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-162", JourneyContentKind.SATIRE, "Ich habe meinen Anschluss visualisiert. Er hat sich trotzdem nicht manifestiert.", "I visualised my connection. It still didn't manifest.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-163", JourneyContentKind.SATIRE, "Am Gleis wird aus „Ich lese kurz“ plötzlich „Ich habe den zweiten Band bestellt“.", "On the platform, I'll read a little becomes I've ordered the second volume.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-164", JourneyContentKind.SATIRE, "Die aktuelle Wagenreihung ist ein persönliches Wachstumsthema für meinen Schrittzähler.", "The current coach order is a personal-growth opportunity for my step counter.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-165", JourneyContentKind.SATIRE, "Mein Zug hat eine kreative Phase. Heute interpretiert er „direkt“ sehr frei.", "My train is in a creative phase. Today it's interpreting direct very freely.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-166", JourneyContentKind.SATIRE, "Die DB hat meinen Termin nicht abgesagt. Sie hat nur die Anreise zur offenen Forschungsfrage gemacht.", "The railway hasn't cancelled my appointment. It's merely made getting there an open research question.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-167", JourneyContentKind.SATIRE, "Ich steige gern um. Aber nicht meine komplette Lebensplanung.", "I'm happy to change trains, less happy to change my entire life plan.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-168", JourneyContentKind.SATIRE, "Der Bahnhof ist ein Coworking-Space, in dem alle dieselbe ungelöste Aufgabe haben: wegkommen.", "The station is a coworking space where everyone shares one unsolved task: leaving.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-169", JourneyContentKind.SATIRE, "Meine Verbindung wurde aktualisiert. Mein Optimismus verwendet noch die alte Version.", "My journey was updated. My optimism is still running the old version.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-170", JourneyContentKind.SATIRE, "Die Abfahrtstafel macht heute Improvisationstheater. Das Publikum steht bereits.", "The departure board is doing improv today. The audience is already standing.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-171", JourneyContentKind.SATIRE, "„Wagen fehlt.“ Schön, dass wenigstens meine Reservierung in der Theorie mitfährt.", "Coach missing. Nice that my reservation is at least travelling in theory.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-172", JourneyContentKind.SATIRE, "Ich habe einen Plan B. Die Bahn fragt gerade nach meinem Alphabetvorrat.", "I have a plan B. The railway is asking how much alphabet I have left.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-173", JourneyContentKind.SATIRE, "Mein Zug und mein WLAN haben viel gemeinsam: Beide werden angezeigt, beide sind gerade schwer erreichbar.", "My train and my Wi-Fi have much in common: both are listed, both are hard to reach.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-174", JourneyContentKind.SATIRE, "Die DB macht mein Wochenende länger. Leider beginnt der Zusatzteil am Bahnhof.", "The railway extends my weekend. Unfortunately, the extra part starts at the station.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-175", JourneyContentKind.SATIRE, "Der nächste Anschluss ist kein Transportmittel mehr, sondern ein Bewerbungsverfahren.", "The next connection is no longer transport; it's an application process.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-176", JourneyContentKind.SATIRE, "Bahnfahren ist mein Strategiespiel. Die Karte ist echt, die Regeln kommen unterwegs.", "Train travel is my strategy game. The map is real; the rules arrive en route.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-177", JourneyContentKind.SATIRE, "Ich packe inzwischen nach Themen: Kleidung, Ladekabel, Snacks und Verhandlungsspielraum.", "I pack by theme now: clothes, charger, snacks and room for negotiation.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-178", JourneyContentKind.SATIRE, "Die Deutsche Bahn bringt Menschen zusammen. Besonders die aus drei Zügen in einem.", "German rail brings people together, especially passengers from three trains inside one.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-179", JourneyContentKind.SATIRE, "Mein Kalender hat Termine. Die Bahn nennt das Fan-Fiction.", "My calendar has appointments. The railway calls that fan fiction.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-180", JourneyContentKind.SATIRE, "Der Zug fährt „abweichend“. Meine Stirnfalte inzwischen auch.", "The train is running differently today. So is the crease in my forehead.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-181", JourneyContentKind.SATIRE, "Ich wollte unterwegs abschalten. Die Anzeigetafel hat angefangen.", "I wanted to switch off en route. The departure board went first.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-182", JourneyContentKind.SATIRE, "„Anschluss wird erreicht.“ Mein persönlicher Lieblingssatz aus dem Genre Hoffnung.", "Connection will be made. My favourite line from the hope genre.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-183", JourneyContentKind.SATIRE, "Meine Rückfahrt braucht keine Playlist. Sie hat bereits mehrere überraschende Übergänge.", "My return journey needs no playlist. It already has several unexpected transitions.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-184", JourneyContentKind.SATIRE, "Ich habe eine Reiseversicherung. Gibt es die auch für den ersten Kaffee nach dem Umstiegssprint?", "I have travel insurance. Does it cover the first coffee after a connection sprint?", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-185", JourneyContentKind.SATIRE, "DB-Romantik: Gemeinsam auf denselben Zug warten, ohne je nach der Telefonnummer zu fragen.", "Railway romance: waiting together for the same train without ever asking for a phone number.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-186", JourneyContentKind.SATIRE, "Mein Schienenersatzverkehr heißt heute „Ich rufe mal jemanden an“.", "Today's replacement service is called I'll phone someone.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-187", JourneyContentKind.SATIRE, "Ein freier Sitzplatz im vollen Zug ist wie ein Sonderangebot: Man prüft erst den Haken.", "An empty seat on a packed train is like a special offer: first you check the catch.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-188", JourneyContentKind.SATIRE, "Ich wollte die Landschaft genießen. Diesen Signalstandort kenne ich jetzt sehr genau.", "I wanted to enjoy the scenery. I now know this particular signal location very well.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-189", JourneyContentKind.SATIRE, "Die Bahnsteigkante ist meine neue Denkterrasse. Nur der Meerblick fehlt.", "The platform edge is my new contemplation terrace. Only the sea view is missing.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-190", JourneyContentKind.SATIRE, "Die App sagt „Reise fortsetzen“. Mein innerer Reiseleiter braucht erst eine Teamsitzung.", "The app says continue journey. My inner tour guide needs a team meeting first.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-191", JourneyContentKind.SATIRE, "Ich fahre klimafreundlich und trainiere nebenbei konfliktfreie Gespräche mit Anzeigetafeln.", "I travel sustainably while practising peaceful conversations with departure boards.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-192", JourneyContentKind.SATIRE, "Der einzige pünktliche Teil meiner Zugreise war heute die Erinnerung, früher loszugehen.", "The only punctual part of today's journey was the reminder to leave earlier.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-193", JourneyContentKind.SATIRE, "Mein Zug ist nicht verschwunden. Er hat seine Sichtbarkeit auf „nur enge Freunde“ gestellt.", "My train hasn't vanished. It's set its visibility to close friends only.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-194", JourneyContentKind.SATIRE, "Die Deutsche Bahn hat aus meiner Kurzstrecke ein Kennenlernwochenende mit dem Nahverkehr gemacht.", "German rail turned my short trip into a getting-to-know-local-transport weekend.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-195", JourneyContentKind.SATIRE, "„Bitte nicht alle in denselben Wagen einsteigen.“ Wir würden gern, aber das ist gerade der ganze Zug.", "Please don't all board the same coach. We'd love not to, but that's the whole train today.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-196", JourneyContentKind.SATIRE, "Ich habe den Bahnsteig gewechselt. Meine gute Laune wurde dort leider nicht bereitgestellt.", "I've changed platforms. Unfortunately, my good mood wasn't provided there.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-197", JourneyContentKind.SATIRE, "Meine Reise ist jetzt interaktiv: Bei jedem Umstieg darf ich neu entscheiden, wie mutig ich bin.", "My journey is interactive now: every change lets me decide how brave I feel.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-198", JourneyContentKind.SATIRE, "Im Zug habe ich endlich Ruhe zum Nachdenken. Zum Beispiel darüber, warum wir nicht fahren.", "On the train I finally have peace to think, for example about why we aren't moving.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-199", JourneyContentKind.SATIRE, "Die Verspätungsanzeige und ich sind jetzt per Du. Wir verbringen einfach zu viel Zeit miteinander.", "The delay display and I are on first-name terms now. We spend too much time together.", null, "Öpen-V · eigene Formulierung", null),
    JourneyContent("satire-200", JourneyContentKind.SATIRE, "Ich buche keine Bahnreise. Ich beginne eine Kampagne mit zufälligen Ereignissen.", "I don't book a train trip. I start a campaign with random events.", null, "Öpen-V · eigene Formulierung", null),
) }
